window.JASTROW_CHUNKS[1023]={"41712":{"h":"מָרֵיקָה","r":"KRU12061","alt":[],"source":"krupnik","glosses":[{"text":"a sort of earth used for polishing","label":""}],"html":"<p>קרקע המיוחד למירוק a sort of earth used for polishing  תוס׳ מקוא׳ ו׳ (ז׳), י״ג: ור׳ יוסי מטמא בשל מריקה מפני ששפין בו סידקי כלים.</p>","notation":["ז׳"]},"41713":{"h":"מָרִיר","r":"KRU12062","alt":[],"source":"krupnik","glosses":[{"text":"bitter","label":""}],"html":"<p>,מְרִירָא ת׳, מר bitter  שבת קכ״ז ע״ב: כיון דמריר לא אכלה; תרג׳ בר׳ כ״ז ל״ד (צעקה גדולה ומרה): צווחתא רבא ומרירא.</p>","notation":[]},"41714":{"h":"מְרִירָה","r":"KRU12063","alt":["מְרִירוּת"],"source":"krupnik","glosses":[{"text":"bitterness","label":""}],"html":"<p>טעם מר, דבר מר bitterness  שמו״ר פמ״ג: חלי מרירתן של ישראל; ויק״ר פי״ב: הללו הביאו מרירות לעולם; תרג׳ מש׳ י״ד י׳ (מרת נפשו): מרירותא דנפשיה.</p>","notation":[]},"41715":{"h":"מְרִירְתָּא","r":"KRU12064","alt":[],"source":"krupnik","glosses":[{"text":"gall","label":""}],"html":"<p>מרה gall  כת׳ נ׳ ע״א: מרירתא דדיה.</p>","notation":["נ׳"]},"41716":{"h":"מָרֵישׁ","r":"KRU12065","alt":["מָרֵישָׁא"],"source":"krupnik","glosses":[{"text":"beam","label":""}],"html":"<p>קורה beam  גיט׳ פ״ה מ״ה: המריש הגזול שבנאו בדירה; תרג׳ חבק׳ ב׳ י״א (וכפיס מעץ): ושפא מגו מרישא.</p>","notation":[]},"41717":{"h":"מרך","r":"KRU12066","alt":[],"source":"krupnik","glosses":[{"text":"to be softened","label":"נתפ׳,"}],"html":"<p>נתפ׳, נִתְמָרֵךְ נתרכך ונתמזמז to be softened  חול׳ מ״ה ע״ב: נתמרך פסול וכו׳ המרכה כל שנשפך וכו׳.</p>","notation":["Source marks no qal form"]},"41718":{"h":"מַרְכְּבָנָא","r":"KRU12067","alt":[],"source":"krupnik","glosses":[{"text":"chariot-driver","label":""}],"html":"<p>רַכב, נוהג המרכבה chariot-driver  תרג׳ מל״א כ״ב ל״ד (ויאמר לרכבו): ואמר למרכבניה.</p>","notation":["ז׳"]},"41719":{"h":"מַרְכּוֹף","r":"KRU12069","alt":[],"source":"krupnik","glosses":[{"text":"a musical instrument","label":""}],"html":"<p>מין כלי זמר a musical instrument  כל׳ פט״ו מ״ו: המרכוף טהור.</p>","notation":["ז׳"]},"41720":{"h":"מרמהין","r":"KRU12071","alt":[],"source":"krupnik","glosses":[{"text":"marjoram","label":""}],"html":"<p>מין צמח marjoram  גיט׳ ס״ט ע״ב: גווזא דמרמהין.</p>","notation":["ז׳","Source emendation: מַרְמָהוּז"]},"41721":{"h":"מַרְמוּצִי","r":"KRU12072","alt":[],"source":"krupnik","glosses":[{"text":"wound","label":""}],"html":"<p>פצע wound  קהל״ר ו׳ י״א: או חד תוקלא או חד מרמוצי.</p>","notation":["נ׳"]},"41722":{"h":"מַרְמֵטָא","r":"KRU12073","alt":["מַרְמֵיטָה"],"source":"krupnik","glosses":[{"text":"cramp, catalepsy","label":""}],"html":"<p>שבץ cramp, catalepsy  ב״ר פי״ז: שלש תרדמות הן תרדמת שינה ותרדמת נבואה ותרדמת מרמיטה; ילק׳ בר׳ כ״ג: מרמטא.</p>","notation":[]},"41723":{"h":"מַרְמַירָא","r":"KRU12074","alt":[],"source":"krupnik","glosses":[{"text":"marble","label":""}],"html":"<p>אבן שיש marble  תרג׳ דחי״א כ״ט ב׳ (שיש): מרמירא.</p>","notation":["ז׳"]},"41724":{"h":"מְרַמְצָא","r":"KRU12075","alt":[],"source":"krupnik","glosses":[{"text":"casing, ouch","label":""}],"html":"<p>משבצת, מלואים casing, ouch  תרג׳ שמ׳ כ״ח י״ג (משבצות): מרמצן.</p>","notation":["נ׳"]},"41725":{"h":"מַרֵס","r":"KRU12077","alt":[],"source":"krupnik","glosses":[{"text":"to crush, to stir","label":"פיעל,"}],"html":"<p>פיעל, מרח וכתת, בלל to crush, to stir  אסת״ר א׳ י״ד: שהיה ממרס את הסלתות; יומא פ״ד מ״ג: וקבל במזרק את דמו ונותנו למי שהוא ממרס.</p>","notation":[]},"41726":{"h":"מַרַע","r":"KRU12078","alt":[],"source":"krupnik","glosses":[{"text":"weakening","label":""}],"html":"<p>התשה weakening  ירוש׳ ב״מ פ״א ח׳ ע״א: מפני מרע כחן של לקוחות.</p>","notation":["ז׳"]},"41727":{"h":"מְרַע","r":"KRU12079","alt":[],"source":"krupnik","glosses":[{"text":"to fall sick","label":"מָרַע פַעל,"},{"text":"to make sick","label":"אַמְרַע אפ׳,"},{"text":"to feign sickness","label":"אִתְמְרַע אתפ׳, 2"}],"html":"<p>מָרַע פַעל, היה חולה to fall sick  תרג׳ דהי״ב ט״ז י״ב (וגם בחליו לא דרש את ה׳): ואוף כד מרע לא תבע אולפן; ירמ׳ י״ד י״ח (תחלואי רעב): ממרעי כפנא.\nאַמְרַע אפ׳, החלה to make sick  תרג׳ ירוש׳ בר׳ ג׳ ט״ו: ממרע יתהון.\nאִתְמְרַע אתפ׳, 1 עי׳ מְרַע. תרג׳ דהי״ב י״ח ל״ג (החליתי): אתמרעית. \nאִתְמְרַע אתפ׳, 2 התחפש לחולה to feign sickness  תרג׳ ש״ב י״ג ה׳ (והתחל): ואתמרע.</p>","notation":["פ״ע"]},"41728":{"h":"מְרַע²","r":"KRU12080","alt":[],"source":"krupnik","glosses":[{"text":"sick","label":"1"},{"text":"sickness","label":"2"}],"html":"<p>1  sick  תרג׳ יב״ע בר׳ י״ח א׳: מרע מכיבא. ועי׳ שְׁכִיב מְרַע.\n2  sickness  תרג׳ מל״א ח׳ ל״ז (כל מחלה): כל מרע.</p>","notation":[]},"41729":{"h":"מַרְעֵי","r":"KRU12084","alt":[],"source":"krupnik","glosses":[{"text":"pasture","label":"1"},{"text":"dung","label":"2"}],"html":"<p>1 מרעה pasture  תרג׳ יב״ע בר׳ י״ג ז׳: אתר מרעי.\n2 צואה dung  תרג׳ ירוש׳ ויק׳ ט״ז כ״ז (פרשם): פרעיהון.</p>","notation":["ז׳"]},"41730":{"h":"מַרְעֵלָא","r":"KRU12087","alt":[],"source":"krupnik","glosses":[{"text":"basket","label":""}],"html":"<p>סל basket  ויק״ר פכ״ח: מלא מרעליה תינין.</p>","notation":["ז׳"]},"41731":{"h":"מַרְפֵּא","r":"KRU12089","alt":[],"source":"krupnik","glosses":[{"text":"your health!","label":""}],"html":"<p>ברכה לחולה: רפואה שלימה your health!  תוס׳ שבת ז׳ (ח׳), ח׳: האומר מרפא הרי זה מדרכי האמורי.</p>","notation":["Marked biblical in source"]},"41732":{"h":"מְלַפֵּא","r":"KRU12090","alt":[],"source":"krupnik","glosses":[{"text":"surgeon","label":""}],"html":"<p>רופא surgeon  מכי׳ משפ׳ נזיק׳ ד׳: מרפא שהמית וכו׳.</p>","notation":["ז׳"]},"41733":{"h":"מַרְפֵּיד","r":"KRU12091","alt":[],"source":"krupnik","glosses":[{"text":"dwelling (the Temple)","label":""}],"html":"<p>רפידה, משכן, כנוי למקדש dwelling (the Temple)  ילק׳ יש׳ שמ״ה: ביתו מרפידו.</p>","notation":["ז׳"]},"41734":{"h":"מַרְפְּיָיתָה","r":"KRU12092","alt":[],"source":"krupnik","glosses":[{"text":"name of certain fruits","label":""}],"html":"<p>מין פרי העץ name of certain fruits  ירוש׳ מעש׳ פ״א מ״ח ע״ד: כגון אילין מרפייתה.</p>","notation":["נ״ר"]},"41735":{"h":"מרפיס","r":"KRU12093","alt":[],"source":"krupnik","glosses":[{"text":"Memphis in Egypt","label":""}],"html":"<p>עיר נוף במצרים Memphis in Egypt  פסיק׳ ויחי ס״ג ע״ב: נוף – מרפיס.</p>","notation":["Source emendation: מֶנְפִּיס"]},"41736":{"h":"מַרְפֶּסֶת","r":"KRU12094","alt":[],"source":"krupnik","glosses":[{"text":"veranda","label":""}],"html":"<p>יציע שלפני הבית veranda  עיר׳ פ״ה ע״ב: בית שער אכסדרה ומרפסת.</p>","notation":["נ׳"]},"41737":{"h":"מַרְפֵּק","r":"KRU12095","alt":[],"source":"krupnik","glosses":[{"text":"elbow","label":""}],"html":"<p>אציל היד elbow  אהל׳ פ״א מ״ח: שנים בקנה ושנים במרפק אחד בזרוע וכו׳.</p>","notation":["ז׳"]},"41738":{"h":"מַרְצוּף","r":"KRU12097","alt":[],"source":"krupnik","glosses":[{"text":"bag","label":""}],"html":"<p>מין שק bag  כל׳ פ״כ מ״א: השקין והמרצופין.</p>","notation":["ז׳"]},"41739":{"h":"מֵרֵק","r":"KRU12098","alt":[],"source":"krupnik","glosses":[{"text":"to finish","label":"1"},{"text":"to remove, to cleanse (from sin)","label":"2"}],"html":"<p>1 שכלל וגמר to finish  ירוש׳ ר״ה פ״א נ״ז ע״ג: מכיון שהתחיל במצוה אומרים לו מרק.\n2 כילה (עון) to remove, to cleanse (from sin)  ברכ׳ ח׳ ע״א: יסורין ממרקין כל עוונותיו של אדם.</p>","notation":["Marked biblical in source"]},"41740":{"h":"מְרַק","r":"KRU12099","alt":[],"source":"krupnik","glosses":[{"text":"to cleanse","label":""}],"html":"<p>ניקה to cleanse  תרג׳ יש׳ כ״א ה׳: מריקו וצחצחו זיינא.</p>","notation":["פ״י"]},"41741":{"h":"מָרֵק","r":"KRU12100","alt":[],"source":"krupnik","glosses":[{"text":"to pay off","label":""},{"text":"to deduct","label":""},{"text":"to be scoured","label":""},{"text":"to be perfumed","label":""}],"html":"<p>1) כנ״ל. ב״מ ט״ו ע״א: ואשפי ואדכי ואמריק. 2) שילם וסילק to pay off  ירוש׳ כת׳ פ״ו ל׳ ע״ג: בהן דמשביק אנתתיה ולא ממריק לה וכו׳. 3) ניכה to deduct  ב״ר פס״ט: ממרקין ליך מן חוביך. אִתְמְרֵק אתפ׳, 1) נצטחצח to be scoured  תרג׳ ויק׳ ו׳ כ״ח (ומורק): ויתמריק. 2) נמרח to be perfumed  תרג׳ יב״ע שמ׳ ל׳ ל״ב (על בשר אדם לא ייסך): על בישרא דאינשא לא יתמריק. </p>","notation":["פַעל"]},"41742":{"h":"מָרְקָא","r":"KRU12101","alt":[],"source":"krupnik","glosses":[{"text":"diluted","label":""}],"html":"<p>מהול במים diluted  גיט׳ ס״ט ע״ב: חמרא מרקא וכו׳ חמרא חייא.</p>","notation":["ת׳"]},"41743":{"h":"מָרְקוּלִיס","r":"KRU12103","alt":[],"source":"krupnik","glosses":[{"text":"Mercury","label":""}],"html":"<p>אחד מאלהי הרומיים Mercury  סנה׳ פ״ז מ״ו: הזורק אבן למרקוליס זו הוא עבודתו.</p>","notation":[]},"41744":{"h":"מַרְקוֹעַ","r":"KRU12104","alt":[],"source":"krupnik","glosses":[{"text":"patch","label":"1"},{"text":"cake","label":"2"}],"html":"<p>1 חתיכת ארג patch  איכ״ר א׳ א׳ (רבתי, חד כותאה א׳): ובה עשרים וארבע מרקועי.\n2 רקיק cake  ירוש׳ תענ׳ פ״ד ס״ט ע״א: תלת מאוון דגרבין דמרקוע.</p>","notation":["ז׳"]},"41745":{"h":"מרר","r":"KRU12105","alt":[],"source":"krupnik","glosses":[{"text":"to become bitter","label":""}],"html":"<p>הִתְמָרֵר נעשה מר to become bitter  שהש״ר א׳ י״ג: המור הזה כל מי שילקטו ידיו מתמררות.</p>","notation":["Marked biblical in source"]},"41746":{"h":"מֶרֶר","r":"KRU12106","alt":["מְרָרָא"],"source":"krupnik","glosses":[{"text":"bitterness","label":""}],"html":"<p>מרירות bitterness  אסת״ר ג׳ ט׳: בוכים במרר; תרג׳ יר׳ ד׳ י״ח (רעתך כי מר): בשתא ומררא.</p>","notation":[]},"41747":{"h":"מְרָרִיתָא","r":"KRU12107","alt":["מְרַרְתָּא"],"source":"krupnik","glosses":[{"text":"Crowfoot","label":""}],"html":"<p>מין צמח Crowfoot  סוכה י״ג ע״א: מרריתא דאגמא; פס׳ ל״ט ע״א: הוה מהדר אמררתא.</p>","notation":[]},"41748":{"h":"מְרַשְׁוָתָא","r":"KRU12108","alt":[],"source":"krupnik","glosses":[{"text":"mortars","label":""}],"html":"<p>מכתשות mortars  ירוש׳ ב״ב פ״ב י״ג ע״ב: אילין מרשותיה.</p>","notation":["נ״ר"]},"41749":{"h":"מְרַת","r":"KRU12109","alt":[],"source":"krupnik","glosses":[{"text":"juice","label":""}],"html":"<p>עסיס juice  תרג׳ עמ׳ ט׳ י״ג (עסיס): חמר מרת.</p>","notation":["ז׳"]},"41750":{"h":"מָרְתָא","r":"KRU12110","alt":["מָרְתָה"],"source":"krupnik","glosses":[{"text":"lady","label":"1"},{"text":"a woman’s name","label":"2"}],"html":"<p>1 אדונה, גברת lady  ירוש׳ חג׳ פ״ב ע״ז ע״ד: מרתה דביתא; ב״ר פנ״ב: מרתא דבעלה.\n2 שם אשה a woman’s name  גיט׳ נ״ו ע״א: מרתא בת בייתוס; שמו״ר פנ״א: שמואל בר מרתה.</p>","notation":[]},"41751":{"h":"מַרְתּוֹקָא","r":"KRU12112","alt":[],"source":"krupnik","glosses":[{"text":"fist","label":"1"},{"text":"blow with the fist","label":"2"}],"html":"<p>1 אגרוף fist  תרג׳ יב״ע שמ׳ כ״א י״ח (באגרוף): במרתוקא.\n2 מכת אגרוף blow with the fist  ירוש׳ מו״ק פ״ג פ״ג ע״ב: ויהב ליה חד מרתוקא גו ליביה.</p>","notation":["ז׳"]},"41752":{"h":"מַרְתְּחָא","r":"KRU12113","alt":[],"source":"krupnik","glosses":[{"text":"frying pan","label":""}],"html":"<p>מחבת frying pan  תרג׳ יב״ע ויק׳ ב׳ ז׳ (מרחשת): מרתחא.</p>","notation":["ז׳"]},"41753":{"h":"מָרְתְּכָא","r":"KRU12115","alt":[],"source":"krupnik","glosses":[{"text":"alloy of lead and silver","label":""}],"html":"<p>תערובת עופרת וכסף alloy of lead and silver  גיט׳ פ״ה ע״א: ומרתכא וכבריתא וכו׳.</p>","notation":["ז׳"]},"41754":{"h":"מַרְתֵּף","r":"KRU12116","alt":[],"source":"krupnik","glosses":[{"text":"cellar","label":""}],"html":"<p>אוצר מתחת לקרקע cellar  ירוש׳ פסח׳ פ״א כ״ז ע״ב: מרתף של יין וכו׳ מרתף של שמן.</p>","notation":["ז׳"]},"41755":{"h":"מִשֶּׁ־","r":"KRU12119","alt":[],"source":"krupnik","glosses":[{"text":"after, since, as soon as","label":""}],"html":"<p>משעה ש־ after, since, as soon as  סוטה פ״ט מ״ז: משנתערפה העגלה; שם מי״א; משבטלה סנהדרין בטלה השיר.</p>","notation":[]},"41756":{"h":"מַשָּׂא","r":"KRU12121","alt":[],"source":"krupnik","glosses":[{"text":"business, intercourse, dealings","label":""}],"html":"<p>מַשָּׂא וּמַתָּן עסק, שיח ושיג business, intercourse, dealings  שבת ק״כ ע״א: כאן בדברי תורה כאן במשא ומתן; יומא פ״ו ע״א: משאו ומתנו בנחת עם הבריות.</p>","notation":["Marked biblical in source"]},"41757":{"h":"מַשְׂאוֹי","r":"KRU12122","alt":[],"source":"krupnik","glosses":[{"text":"burden","label":""}],"html":"<p>משא burden  שבת צ״ב ע״א: המוציא משאוי.</p>","notation":["ז׳"]},"41758":{"h":"מְשָׁאכָא","r":"KRU12124","alt":[],"source":"krupnik","glosses":[{"text":"length","label":""}],"html":"<p>אורך length  ב״ב ע״ג ע״ב: משאכא דצואריה תלתא פרסי.</p>","notation":["ז׳"]},"41759":{"h":"מִשְׁאָר","r":"KRU12125","alt":[],"source":"krupnik","glosses":[{"text":"the rest of","label":""}],"html":"<p>שארית, יתר the rest of  תרג׳ יב״ע במ׳ י״ט ג׳: משאר בעירן.</p>","notation":["ז׳"]},"41760":{"h":"מַשָׁארָא","r":"KRU12126","alt":[],"source":"krupnik","glosses":[{"text":"garden-) bed","label":""}],"html":"<p>ערוגה (garden-) bed  קיד׳ ל״ט ע״א: רב זרע ליה גינתא דבי רב משארי משארי.</p>","notation":["ז׳"]},"41761":{"h":"מִשָּׁב","r":"KRU12127","alt":[],"source":"krupnik","glosses":[{"text":"bellows","label":""}],"html":"<p>מפוח bellows  תרג׳ ירמ׳ ו׳ כ״ט (מפוח): משב נפשין.</p>","notation":["ז׳"]},"41762":{"h":"מְשַׁבְּקָא","r":"KRU12128","alt":[],"source":"krupnik","glosses":[{"text":"divorcer, former husband","label":""}],"html":"<p>גרוש divorcer, former husband  ירוש׳ כת׳ פי״א ל״ד ע״ב: שכונה דמשבקי.</p>","notation":["ז׳"]},"41763":{"h":"מְשַׁבַּקְתָּא","r":"KRU12129","alt":[],"source":"krupnik","glosses":[{"text":"divorced wife","label":""}],"html":"<p>גרושה divorced wife  ב״ר פי״ז: משבקתיה אנא.</p>","notation":["נ׳"]},"41764":{"h":"מַשְׁבֵּר","r":"KRU12130","alt":[],"source":"krupnik","glosses":[{"text":"travailing chair","label":""}],"html":"<p>כסא היולדת travailing chair  כל׳ פכ״ג מ״ד: משבר של חיה.</p>","notation":["Marked biblical in source"]},"41765":{"h":"מְשַׁבֶּשְׁתָּא","r":"KRU12131","alt":[],"source":"krupnik","glosses":[{"text":"a faulty version","label":""}],"html":"<p>גירסא משובשת a faulty version  שבת קכ״א ע״ב: מאן נימא לן דהא מתרצתא היא דילמא משבשתא היא.</p>","notation":["נ׳"]},"41766":{"h":"מַשֶּׁהוּ","r":"KRU12133","alt":["מַשֶּׁהוּא"],"source":"krupnik","glosses":[{"text":"anything, minimum","label":""}],"html":"<p>דבר מה, מעט מן המעט anything, minimum  מנח׳ ס׳ ע״א: משהו שמן; ספרי במ׳ ק״ס: הברזל ממית במשהוא; עיר׳ פ״ז ע״א: ושני משהויין.</p>","notation":[]},"41767":{"h":"מַשּׂוֹא","r":"KRU12134","alt":[],"source":"krupnik","glosses":[{"text":"load, burden","label":""}],"html":"<p>משא load, burden  ירוש׳ דמ׳ פ״ב כ״ב ע״ג: הביא שלשה משואין כאחד.</p>","notation":["ז׳"]},"41768":{"h":"מַשּׂוּאָה","r":"KRU12135","alt":[],"source":"krupnik","glosses":[{"text":"fire signal","label":""}],"html":"<p>מדורה לשם אות למרחקים fire signal  ר״ה פ״ב מ״ג: כיצד היו משיאין משואות מביאין כלונסאות וכו׳ ועולה לראש ההר ומצית בהן את האור וכו׳.</p>","notation":["נ׳"]},"41769":{"h":"מְשׁוּבָּח","r":"KRU12136","alt":[],"source":"krupnik","glosses":[{"text":"good, valuable","label":""}],"html":"<p>טוב ומעולה good, valuable  שהש״ר א׳ א׳: המשובח שבשירים.</p>","notation":["ת׳"]},"41770":{"h":"מְשׁוּבָּשׁ","r":"KRU12137","alt":[],"source":"krupnik","glosses":[{"text":"thrown into confusion","label":""}],"html":"<p>מסוכסך thrown into confusion  יבמ׳ פט״ז מ״ז: שהמדינה הזאת משובשת בגייסות.</p>","notation":["ת׳"]},"41771":{"h":"מַשְׁוַורְתָּא","r":"KRU12138","alt":[],"source":"krupnik","glosses":[{"text":"leaping","label":""}],"html":"<p>קפיצה leaping  סנהד׳ ס״ד ע״ב: כמשוורתא דפורייא.</p>","notation":["נ׳"]},"41772":{"h":"מָשׁוֹחַ","r":"KRU12139","alt":["מְשׁוֹחָאָה"],"source":"krupnik","glosses":[{"text":"surveyor","label":""}],"html":"<p>מודד קרקעות surveyor  כל׳ פי״ד מ״ג: שלשלת של משוחות; ב״מ ק״ז ע״ב: א״ל ר׳ יהודה לר׳ אדא משוחאה.</p>","notation":[]},"41773":{"h":"מְשׁוּחָק","r":"KRU12140","alt":[],"source":"krupnik","glosses":[{"text":"rubbed, worn-out","label":""}],"html":"<p>בלה מרוב שמוש rubbed, worn-out  תוס׳ מנח׳ א׳ ח׳: בגדיו משוחקין.</p>","notation":["ת׳"]},"41774":{"h":"מָשׁוּךְ","r":"KRU12142","alt":[],"source":"krupnik","glosses":[{"text":"one who has his prepuce drawn forward","label":""}],"html":"<p>מי שמושך בערלתו one who has his prepuce drawn forward  יבמ׳ ע״ב ע״א: משוך וכו׳ שנראה כערל וכו׳.</p>","notation":["ז׳"]},"41775":{"h":"מְשׁוּלַחַת","r":"KRU12143","alt":[],"source":"krupnik","glosses":[{"text":"a divorced wife taken back after being married to another man","label":""}],"html":"<p>גרושה ששבה לאישה הראשון לאחר שהיתה נשואה לאיש אחר a divorced wife taken back after being married to another man  נדה ס״ט ע״ב: בת משולחת מה היא לכהן.</p>","notation":["נ׳"]},"41776":{"h":"מְשׁוּלָל","r":"KRU12144","alt":[],"source":"krupnik","glosses":[{"text":"to be decorated with","label":""}],"html":"<p>מקושט to be decorated with  מכי׳ בשלח א׳: משוללין בזיין.</p>","notation":["ת׳"]},"41777":{"h":"מְשׁוּמָד","r":"KRU12145","alt":[],"source":"krupnik","glosses":[{"text":"apostate","label":""}],"html":"<p>מומר apostate  ירוש׳ עיר׳ פ״ו כ״ג ע״ב: משומד בגילוי פנים הרי הוא כגוי לכל.</p>","notation":["ז׳"]},"41778":{"h":"מְשׁוּמָם","r":"KRU12146","alt":[],"source":"krupnik","glosses":[{"text":"confused","label":""}],"html":"<p>נבוך confused  תוס׳ כת׳ ז׳ י׳: משוממת היא.</p>","notation":["ת׳"]},"41779":{"h":"מְשׁוּמְשָׁנָא","r":"KRU12147","alt":[],"source":"krupnik","glosses":[{"text":"servant","label":""}],"html":"<p>משרת, שַמש servant  קהל״ר א׳ ג׳: והוה רבי אומר למשומשנוהי.</p>","notation":["ז׳"]},"41780":{"h":"מְשׁוּמָת","r":"KRU12148","alt":[],"source":"krupnik","glosses":[{"text":"excommunicated","label":""}],"html":"<p>מוחרם excommunicated  שבת ס״ז ע״א: ליטא תבור ומשומת.</p>","notation":["ת׳"]},"41781":{"h":"מְשׁוּנֶה","r":"KRU12149","alt":[],"source":"krupnik","glosses":[{"text":"different, strange","label":""}],"html":"<p>נבדל ושונה different, strange  ירוש׳ תענ׳ פ״א קנ״ו ע״ב: מיתה משונה.</p>","notation":["ת׳"]},"41782":{"h":"מְשׁוּנִיתָא","r":"KRU12150","alt":[],"source":"krupnik","glosses":[{"text":"grotto","label":""}],"html":"<p>מערה grotto  ב״ר פ״י: הוה קאים ומטייל על משוניתא דימא דקיסרין.</p>","notation":["נ׳"]},"41783":{"h":"מְשׁוּעֲמָם","r":"KRU12151","alt":[],"source":"krupnik","glosses":[{"text":"dull","label":""}],"html":"<p>חסר דעה dull  ב״מ פ׳ ע״א: משועממת.</p>","notation":["ת׳"]},"41784":{"h":"מְשׁוֹעֵר","r":"KRU12152","alt":[],"source":"krupnik","glosses":[{"text":"gate-keeper","label":""}],"html":"<p>שוער, שומר הפתח gate-keeper  ערכ׳ י״א ע״ב: משוער ששורר.</p>","notation":["ז׳"]},"41785":{"h":"מְשׁוּפָּע","r":"KRU12153","alt":[],"source":"krupnik","glosses":[{"text":"slanting","label":"1"}],"html":"<p>1 נטוי במורד slanting  ירוש׳ נד׳ פ״ה ל״ט ע״א: היה המקום משופע.\n2 עי׳ מְשׁוּפָּשׁ. ילק׳ ויק׳ תקע״א: דרך משופע. </p>","notation":["ת׳"]},"41786":{"h":"מְשׁוּפָּשׁ","r":"KRU12154","alt":[],"source":"krupnik","glosses":[{"text":"curved","label":""}],"html":"<p>מעוקל, עקלקל curved  מנ׳ כ״ז ע״ב: דרך משופש.</p>","notation":["ת׳"]},"41787":{"h":"מְשׁוֹרְיָא","r":"KRU12156","alt":[],"source":"krupnik","glosses":[{"text":"journey","label":""}],"html":"<p>מסע journey  תרג׳ יב״ע במ׳ כ״א א׳: משוריין.</p>","notation":["נ׳"]},"41788":{"h":"מְשׁוּתָּת","r":"KRU12158","alt":[],"source":"krupnik","glosses":[{"text":"founded","label":""}],"html":"<p>מיוסד founded  סנה׳ כ״ו ע״ב: שהעולם משותת עליהן.</p>","notation":["ת׳"]},"41789":{"h":"מְשֵׁזִיב","r":"KRU12159","alt":[],"source":"krupnik","glosses":[{"text":"refugee","label":""}],"html":"<p>פליט refugee  תרג׳ דב׳ ג׳ ג׳ (שריד): משזיב.</p>","notation":["ז׳"]},"41790":{"h":"מְשַׁח","r":"KRU12160","alt":[],"source":"krupnik","glosses":[{"text":"to rub with oil","label":""},{"text":"to measure","label":""},{"text":"to be rubbed with oil","label":""}],"html":"<p>1) סך בשמן to rub with oil  תרג׳ שמ׳ כ״ט ב׳ (משוחים בשמן): דמשיחין במשח. 2) מדד to measure  תרג׳ זכ׳ ב׳ ו׳ (למוד את ירושלים): למימשח ית ירושלם. אִיתְמְשַׁח אתפ׳, נמשח to be rubbed with oil  תרג׳ עמ׳ ו׳ ו׳ (וראשית שמנים ימשחו): וריש משחין טבין מתמשחין. </p>","notation":["פ״י"]},"41791":{"h":"מְשַׁח²","r":"KRU12161","alt":["מִשְׁחָא"],"source":"krupnik","glosses":[{"text":"oil","label":"1"},{"text":"fat","label":"2"},{"text":"measure","label":"3"}],"html":"<p>1 שמן oil  תרג׳ שמ׳ כ״ט ז׳ (שמן המשחה): משחא דרבותא; במ׳ ז׳ י״ג (בלולה בשמן): דפילא במשח.\n2 שומן fat  ע״ז כ״ח ע״א: משחא דאווזא.\n3 מדה measure  תרג׳ דהי״ב ד׳ ב׳ (וקו): וחוט משח.</p>","notation":[]},"41792":{"h":"מִשְׁחֶזֶת","r":"KRU12162","alt":[],"source":"krupnik","glosses":[{"text":"whetting implement","label":""}],"html":"<p>כלי להשחזה וללטישה whetting implement  ביצה כ״ח ע״א: לא שנו אלא במשחזת של אבן אבל במשחזת של עץ מותר.</p>","notation":["נ׳"]},"41793":{"h":"מִשְׁחָן","r":"KRU12163","alt":[],"source":"krupnik","glosses":[{"text":"pine","label":"1"},{"text":"oil","label":"2"}],"html":"<p>1 מין אילן pine  סוכה מ׳ ע״א: עצים דמשחן.\n2 שמן oil  תרג׳ שני אס׳ ו׳ י״א: משחנין טבין.</p>","notation":["ז׳"]},"41794":{"h":"מִשְׁחֲתָא","r":"KRU12164","alt":[],"source":"krupnik","glosses":[{"text":"measure, length","label":""}],"html":"<p>מדה, אורך measure, length  שבת ע״ד ע״ב: קפיד אמשחתא.</p>","notation":["נ׳"]},"41795":{"h":"מִשְׁטֵיחַ","r":"KRU12165","alt":[],"source":"krupnik","glosses":[{"text":"layer","label":""}],"html":"<p>שכבה layer  ספרי במ׳ צ״ח: שהיתה עשויה משטיחים משטיחים.</p>","notation":["ז׳"]},"41796":{"h":"מְשֵׁי","r":"KRU12167","alt":[],"source":"krupnik","glosses":[{"text":"to touch","label":""},{"text":"to wash","label":""},{"text":"to dip in","label":""}],"html":"<p>1) משש to touch  תרג׳ בר׳ כ״ז כ״ב (וימשהו): ומשייה. 2) רחץ to wash  בר׳ מ״ו ע״ב: משי ידך. אַמְשֵׁי  אפ׳, שרה במים to dip in  ב״ב קנ״ג ע״א: אמשינהו למניה דרבא במיא. </p>","notation":["פ״י"]},"41797":{"h":"מְשֵׁיזֵבְתָּא","r":"KRU12169","alt":[],"source":"krupnik","glosses":[{"text":"deliverance","label":""}],"html":"<p>מפלט והצלה deliverance  תרג׳ עוב׳ א׳ י״ז (פליטה): משיזבתא.</p>","notation":["נ׳"]},"41798":{"h":"מָשִׁיחַ","r":"KRU12171","alt":[],"source":"krupnik","glosses":[{"text":"the Messiah, the future redeemer of Israel","label":""}],"html":"<p>הגואל המקווה the Messiah, the future redeemer of Israel  בר׳ ל״ד ע״ב: כל הנביאים כולן לא נתנבאו אלא לימות המשיח.</p>","notation":["Marked biblical in source"]},"41799":{"h":"מְשִׁיחָא","r":"KRU12172","alt":[],"source":"krupnik","glosses":[{"text":"anointed","label":"2"},{"text":"rope","label":"3"}],"html":"<p>1 כנ״ל. סנהד׳ נ״א ע״ב: הלכתא למשיחא. \n2 משוח למלכות anointed  תרג׳ ש״א כ״ד ו׳ (משיח ה׳): משיחא דה׳.\n3 חבל rope  ירוש׳ כת׳ פי״ב ל״ה ע״א: ייבון משיחא בריגלוי.</p>","notation":["ז׳"]},"41800":{"h":"מְשִׁיחָה","r":"KRU12173","alt":[],"source":"krupnik","glosses":[{"text":"anointing","label":"1"},{"text":"cord","label":"2"}],"html":"<p>1 סיכה בשמן anointing  במ״ר פי״ב: משיחת אהרן כיצד.\n2 פתיל cord  כל׳ פכ״א מ״ג: בחוט ובמשיחה.</p>","notation":["נ׳"]},"41801":{"h":"מְשִׁיחוּת","r":"KRU12174","alt":[],"source":"krupnik","glosses":[{"text":"highpriesthood","label":""}],"html":"<p>כהונה גדולה highpriesthood  הור׳ פ״ג מ״א: כהן משיח וכו׳ עבר ממשיחותו.</p>","notation":["נ׳"]},"41802":{"h":"מְשִׁיחֲתָא","r":"KRU12175","alt":[],"source":"krupnik","glosses":[{"text":"rope","label":""}],"html":"<p>חבל, משיחה rope  ירוש׳ כלא׳ פ״ט ל״ב ע״ג: יהבון משיחתא ברגליי.</p>","notation":["נ׳"]},"41803":{"h":"מִשָׁיְילָא","r":"KRU12176","alt":[],"source":"krupnik","glosses":[{"text":"request","label":""}],"html":"<p>משאלה request  תרג׳ תה׳ ל״ז ד׳ (משאלת לבך): משיילי ליבך.</p>","notation":["ז׳"]},"41804":{"h":"מְשִׁיכָה","r":"KRU12177","alt":[],"source":"krupnik","glosses":[{"text":"drawing","label":"1"},{"text":"persuasion","label":"2"},{"text":"taking possession by drawing towards oneself the object to be acquired","label":"3"}],"html":"<p>1 פעולת המושך drawing  ירוש׳ ב״ק פ״י ז׳ ע״ג: משיחת המחט.\n2 לקיחת הלב persuasion  במ״ר פי״ח: ויקח קרח וכו׳ אין ויקח אלא משיכת דברים רכים.\n3 צורת קנין במטלטלים taking possession by drawing towards oneself the object to be acquired  קיד׳ פ״א מ״ד: בהמה דקה נקנית במשיכה.</p>","notation":["נ׳"]},"41805":{"h":"מְשִׁיכוּתָא","r":"KRU12178","alt":[],"source":"krupnik","glosses":[{"text":"basin","label":""}],"html":"<p>כיור basin  חול׳ מ״ז ע״ב: משיכותא דמיא.</p>","notation":["נ׳"]},"41806":{"h":"מְשִׁיכְלָא","r":"KRU12179","alt":[],"source":"krupnik","glosses":[{"text":"a sort of cloak","label":"2"}],"html":"<p>1 כנ״ל. ב״מ פ״ד ע״ב: שיתין משיכלי דמיא.\n2 מין בגד a sort of cloak  ויק״ר פכ״ג: שמיכה וכו׳ – במשיכלא.</p>","notation":["ז׳"]},"41807":{"h":"מְשִׁילְיָא","r":"KRU12180","alt":[],"source":"krupnik","glosses":[{"text":"fork","label":""}],"html":"<p>מזלג fork  תרג׳ ש״א ב׳ י״ד (כל אשר יעלה המזלג): כל דמסיק משיליא.</p>","notation":["ז׳"]},"41808":{"h":"מְשִׂימָה","r":"KRU12181","alt":[],"source":"krupnik","glosses":[{"text":"office","label":""}],"html":"<p>פקידות, משרה office  יב׳ מ״ה ע״ב: כל משימות שאתה משים אל יהו אלא מקרב אחיך.</p>","notation":["נ׳"]},"41809":{"h":"מְשִׁיפָא","r":"KRU12182","alt":[],"source":"krupnik","glosses":[{"text":"embrocation","label":""}],"html":"<p>מירוח embrocation  שבת ע״ז ע״ב: ולובן של ביצה כדי ליתן במשיפה של קילור כדי לשוף במים.</p>","notation":["ז׳"]},"41810":{"h":"מְשִׁירְיָא","r":"KRU12183","alt":[],"source":"krupnik","glosses":[{"text":"camp","label":""}],"html":"<p>מחנה camp  תרג׳ יב״ע במ׳ ד׳ ט״ז (מחנה ראובן): משיריית ראובן.</p>","notation":["נ׳"]},"41811":{"h":"מָשַׁךְ","r":"KRU12184","alt":[],"source":"krupnik","glosses":[{"text":"to take possession by drawing an object","label":""},{"text":"to draw","label":""},{"text":"to conduct water","label":""}],"html":"<p>קנה ע״י משיכה to take possession by drawing an object  ב״מ פ״ד מ״ב: משך הימנו פירות. הִמְשִׁיךְ הפ׳, 1) משך to draw  ירוש׳ כלא׳ פ״ח ל״א ע״ג: הנהיגה המשיכה. 2) העביר מים to conduct water  ירוש׳ מו״ק פ״א פ׳ ע״ב: המשיך המעין לתוכה. </p>","notation":["Marked biblical in source"]},"41812":{"h":"מְשַׁךְ","r":"KRU12185","alt":["מַשְׁכָא"],"source":"krupnik","glosses":[{"text":"hide, skin","label":""}],"html":"<p>עור hide, skin  ירוש׳ נד׳ פ״ג ל״ז ע״ד: משך דחיוי; תנח׳ בר׳ ז׳: הדין ערקא מן הדין משכא; תרג׳ ויק׳ י״ג ג׳ (מעור בשרו): ממשך בשריה.</p>","notation":[]},"41813":{"h":"מַשְׁכּוֹכִית","r":"KRU12186","alt":["משכוביתא"],"source":"krupnik","glosses":[{"text":"bell-wether","label":""}],"html":"<p>השה שהולך בראש העדר bell-wether  ב״ק נ״ב ע״א: המוכר עדר לחבירו כיון שמסר לו משכוכית קנה; תרג׳ יב״ע בר׳ ל׳ מ׳ (פני הצאן): משכוביתא.</p>","notation":[]},"41814":{"h":"מַשְׁכּוֹן","r":"KRU12187","alt":["מַשְׁכּוֹנָא"],"source":"krupnik","glosses":[{"text":"pledge","label":""}],"html":"<p>עבוט, ערבון pledge  ב״מ פ״א ע״ב: המלוה את חבירו על המשכון ואבד המשכון וכו׳: תרג׳ יח׳ י״ח ט״ז (חבול לא חבל): משכונא לא נסיב.</p>","notation":[]},"41815":{"h":"מִשְׁכֵּן","r":"KRU12188","alt":[],"source":"krupnik","glosses":[{"text":"to take a pledge","label":""},{"text":"to be seized as a pledge","label":""}],"html":"<p>לקח עבוט to take a pledge  ב״מ קי״ג ע״ב: שליח בית דין שבא למשכנו. הִתְמַשְׁכֵּן התפ׳, נלקח לעבוט to be seized as a pledge  במ״ר פי״ב: המקדש והמשכן יתמשכנו. </p>","notation":["פ״י"]},"41816":{"h":"מַשְׁכַנְתָּא","r":"KRU12189","alt":[],"source":"krupnik","glosses":[{"text":"mortgaging","label":""}],"html":"<p>משכון, אפותיקי mortgaging  ב״מ ס״ח ע״א: סתם משכנתא שתא.</p>","notation":["נ׳"]},"41817":{"h":"מְשַׁכֵּר","r":"KRU12190","alt":[],"source":"krupnik","glosses":[{"text":"intoxicating drink","label":""}],"html":"<p>משקה המביא לידי שכרון intoxicating drink  ספרא שמיני פרשה א׳: כל המשכרים.</p>","notation":["ז׳"]},"41818":{"h":"מְשַׁלְהֵי","r":"KRU12191","alt":[],"source":"krupnik","glosses":[{"text":"tired","label":""}],"html":"<p>עיף tired  תרג׳ בר׳ כ״ה ל׳ (עיף): משלהי.</p>","notation":["ת׳"]},"41819":{"h":"מִשְׁלַחַת","r":"KRU12192","alt":[],"source":"krupnik","glosses":[{"text":"mission","label":""}],"html":"<p>שליחות mission  במ״ר פי״ד: והיה זריז במשלחתו.</p>","notation":["Marked biblical in source"]},"41820":{"h":"מִשְׁלָם","r":"KRU12194","alt":[],"source":"krupnik","glosses":[{"text":"end","label":""}],"html":"<p>קץ end  ב״מ ס״ז ע״ב: במשלם שניא אילין.</p>","notation":["ז׳"]},"41821":{"h":"מְשֻׁמָּדוּת","r":"KRU12195","alt":[],"source":"krupnik","glosses":[{"text":"apostasy","label":""}],"html":"<p>המרת דת apostasy  ילק׳ שמ׳ רי״א: משמדות פסולות [פוסלת] בפסח.</p>","notation":["נ׳"]},"41822":{"h":"מָשְׁמָהִיג","r":"KRU12196","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ר״ה כ״ג ע״א: פרוותא דמשמהיג. </p>","notation":["שם מקום"]},"41823":{"h":"מַשְׁמוֹטָא","r":"KRU12197","alt":[],"source":"krupnik","glosses":[{"text":"thief","label":""}],"html":"<p>גנב thief  ע״ז ט״ו ע״ב: הכא במאי עסקינן במשמוטא בעלמא.</p>","notation":["ז׳"]},"41824":{"h":"מִשְׁמוּשׁ","r":"KRU12198","alt":[],"source":"krupnik","glosses":[{"text":"touch","label":"1"},{"text":"use","label":"2"}],"html":"<p>1 מישוש touch  ב״ר פנ״ב: משמוש ידים.\n2 שימוש use  עוקצ׳ פ״א מ״ה: רוצה במשמושן.</p>","notation":["ז׳"]},"41825":{"h":"מִשְׁמָע","r":"KRU12199","alt":[],"source":"krupnik","glosses":[{"text":"obedience","label":"1"},{"text":"ordinary sense","label":"2"}],"html":"<p>1 ציות, משמעת obedience  ספרי דברים שנ״ז: אין לך משמע גדול מזה שנאמר ויעשו כאשר צוה ה׳.\n2 פשט ordinary sense  יומא ס״א ע״א: מזבח כמשמעו.</p>","notation":["Marked biblical in source"]},"41826":{"h":"מִשְׁמָרָהֹ","r":"KRU12201","alt":[],"source":"krupnik","glosses":[{"text":"watch","label":""}],"html":"<p>אשמורה watch  בר׳ ג׳ ע״א: משמרה ראשונה.</p>","notation":["Marked biblical in source"]},"41827":{"h":"מְשַׁמֶּרֶת","r":"KRU12202","alt":[],"source":"krupnik","glosses":[{"text":"filter","label":""}],"html":"<p>מסננת filter  אבות פ״ה מ״ו: משמרת שמוציאה את היין וקולטת את השמרים.</p>","notation":["נ׳"]},"41828":{"h":"מִשְׁמֵשׁ","r":"KRU12203","alt":[],"source":"krupnik","glosses":[{"text":"to touch","label":"1"},{"text":"to examine","label":"2"}],"html":"<p>1 משש וגישש to touch  ב״מ כ״א ע״ב: אדם עשוי למשמש בכיסו בכל שעה.\n2 בחן to examine  ערוב׳ י״ג ע״ב: ימשמש במעשיו.</p>","notation":["פ״י"]},"41829":{"h":"מִשְׁמֵשׁ וּבָא","r":"KRU12204","alt":[],"source":"krupnik","glosses":[{"text":"to come near","label":""}],"html":"<p>הלך וקרב to come near  ירוש׳ נדר׳ פ״ג ל״ח ע״א: דליקה ממשמשת ובאה.</p>","notation":[]},"41830":{"h":"מַשְׁמָשׁ","r":"KRU12205","alt":[],"source":"krupnik","glosses":[{"text":"substance","label":""}],"html":"<p>ממשות, עצמיות substance  ירוש׳ בר׳ פ״ו ו׳ ע״ד: מים אין משמשן קיים.</p>","notation":["ז׳"]},"41831":{"h":"מְשַׁמְשָׁנָא","r":"KRU12206","alt":[],"source":"krupnik","glosses":[{"text":"servant","label":""}],"html":"<p>משרת, שַמש servant  ויק״ר פכ״ח: אמר רבי למשמשנוי.</p>","notation":["ז׳"]},"41832":{"h":"מַשְׁמְשָׁנִית","r":"KRU12207","alt":[],"source":"krupnik","glosses":[{"text":"thief","label":""}],"html":"<p>גנבית thief  ב״ר פע״ד: היה מכירה שהיא משמשנית.</p>","notation":["נ׳"]},"41833":{"h":"מִשְׁנָה","r":"KRU12208","alt":[],"source":"krupnik","glosses":[{"text":"study","label":"1"},{"text":"Mishnah, the collection of oral laws edited by R. Judah ha-Nasi","label":"2"}],"html":"<p>1 למוד study  אבות פ״ג מ״ז: תקפה עליו משנתו.\n2 קובץ ההלכות מיסודו של ר׳ יהודה הנשיא Mishnah, the collection of oral laws edited by R. Judah ha-Nasi  אסת״ר א׳ ב׳: ששה סדרי משנה.</p>","notation":["נ׳"]},"41834":{"h":"מַשְׁנֶה","r":"KRU12209","alt":[],"source":"krupnik","glosses":[{"text":"teacher","label":""}],"html":"<p>מלמד, מורה teacher  ויק״ר פ״ח: סופרים ומשנים שהיו מלמדין את התינוקות באמונה.</p>","notation":["ז׳"]},"41835":{"h":"מַשְׁנוֹיָיתָא","r":"KRU12210","alt":["מִשְׁנָיוּתָא"],"source":"krupnik","glosses":[{"text":"squinting","label":""}],"html":"<p>פזול העינים, שאין שתיהן מביטות בכיוון אחד squinting  בכורות מ״ד ע״א: מבלבליתא מתבלול משנוייתא מבעינו; שם: משום משניותא.</p>","notation":[]},"41836":{"h":"מִשְׁפּוּ","r":"KRU12211","alt":[],"source":"krupnik","glosses":[{"text":"wine-sample","label":""}],"html":"<p>מטעמת wine-sample  ב״ר פל״ח: הא משפו דכולא בישא.</p>","notation":["נ׳"]},"41837":{"h":"מַשְׁפֵּךְ","r":"KRU12212","alt":[],"source":"krupnik","glosses":[{"text":"funnel","label":""}],"html":"<p>שפופרת להכנסת נוזלים לתוך כלי צר funnel  אבות פ״ה מט״ו: משפך שמכניס בזו ומוציא בזו.</p>","notation":["ז׳"]},"41838":{"h":"מַשְׁפַּךְ","r":"KRU12213","alt":[],"source":"krupnik","glosses":[{"text":"torrent","label":""}],"html":"<p>מפל מים torrent  תרג׳ דב׳ ד׳ מ״ט (אשדות הפסגה): משפך מרמתא.</p>","notation":["ז׳"]},"41839":{"h":"מִשְׁפֶּלֶת","r":"KRU12214","alt":[],"source":"krupnik","glosses":[{"text":"a basket","label":""}],"html":"<p>מין סל a basket  כל׳ פכ״ד מ״ט: שלש משפלות הן של זבל וכו׳ של תבן וכו׳.</p>","notation":["נ׳"]},"41840":{"h":"מִשְׁקְדָא","r":"KRU12215","alt":[],"source":"krupnik","glosses":[{"text":"shell","label":""}],"html":"<p>קליפת הצב shell  ע״ז כ״ח ע״ב: משקדי חלזוני.</p>","notation":["ז׳"]},"41841":{"h":"מַשְׁקוֹי","r":"KRU12216","alt":[],"source":"krupnik","glosses":[{"text":"drink","label":""}],"html":"<p>משקה drink  קהל״ר ט׳ ט׳: חד משקוי חמים.</p>","notation":["ז׳"]},"41842":{"h":"מַשְׁקוּפִי","r":"KRU12217","alt":[],"source":"krupnik","glosses":[{"text":"bruise","label":""}],"html":"<p>חבורה bruise  תרג׳ שמ׳ כ״א כ״א (חבורה תחת חבורה): משקופי חלף משקופי.</p>","notation":["נ׳"]},"41843":{"h":"מַשְׁקֵי","r":"KRU12218","alt":["מַשְׁקְיָא"],"source":"krupnik","glosses":[{"text":"drink","label":""}],"html":"<p>משקה drink  תרג׳ ויק׳ י״א ל״ד (משקה): משקיא; (יב״ע שם: משקי).</p>","notation":[]},"41844":{"h":"מֵשְׁרָא","r":"KRU12219","alt":[],"source":"krupnik","glosses":[{"text":"garden-bed","label":"1"},{"text":"camp","label":"2"}],"html":"<p>1 ערוגה garden-bed  בכורות ח׳ ע״ב: משרא דסכיני וכו׳ ומי איכא משרא דסכיני.\n2 מחנה camp  תרג׳ יש׳ ז׳ כ״ה: בית משרי עדרין.</p>","notation":["ז׳"]},"41845":{"h":"מִשְׁרָה","r":"KRU12220","alt":[],"source":"krupnik","glosses":[{"text":"steeping","label":"1"},{"text":"a pond for steeping flax etc.","label":"2"}],"html":"<p>1 שריה במים steeping  ב״ק ק״ב ע״א: לאכלה ולא למשרה לאכלה ולא לכבוסה.\n2 בריכה לכביסה a pond for steeping flax etc.  ב״ב ק״ב ע״א: מרחיקין את המשרה מן הירק.</p>","notation":["Marked biblical in source"]},"41846":{"h":"מְשַׁרְוֵי","r":"KRU12221","alt":[],"source":"krupnik","glosses":[{"text":"resting place","label":""}],"html":"<p>תַחנה resting place  תרג׳ תה׳ י״ט ה׳: משרוי זיהרא.</p>","notation":["ז׳"]},"41847":{"h":"מַשְׁרוּנְיָא","r":"KRU12222","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Babylonia","label":""}],"html":"<p>בבבל name of a place in Babylonia  כ״מ ק״ז ע״ב: בני משרוניא.</p>","notation":["שם מקום"]},"41848":{"h":"מַשְׁרוֹעָא","r":"KRU12223","alt":[],"source":"krupnik","glosses":[{"text":"slippery spot","label":""}],"html":"<p>מקום חלקלק slippery spot  תרג׳ יר׳ כ״ג י״ב (כחלקלקות): כמשרועין.</p>","notation":["ז׳"]},"41849":{"h":"מַשְׁרֵי","r":"KRU12224","alt":["מַשְׁרִיתָא"],"source":"krupnik","glosses":[{"text":"camp","label":""}],"html":"<p>מחנה camp  תרג׳ יב״ע שמ׳ י״ד כ׳ (ולא קרב זה אל זה): ולא קבלא משרי כל קבל משרי; תרג׳ בר׳ ל״ב ט׳ (אל המחנה האחת): למשריתא חדא.</p>","notation":[]},"41850":{"h":"מְשַׁרְשְׁיָא","r":"KRU12225","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  בר׳ ו׳ ע״א: א״ל רב משרשיא לבניה.</p>","notation":[]},"41851":{"h":"מִשְׁתָּאֵל","r":"KRU12227","alt":[],"source":"krupnik","glosses":[{"text":"fortune-teller","label":""}],"html":"<p>קוסם fortune-teller  תרג׳ יש׳ ג׳ ב׳ (קסם): משתאל.</p>","notation":["ז׳"]},"41852":{"h":"מַשְׁתּוּיָת","r":"KRU12228","alt":[],"source":"krupnik","glosses":[{"text":"foundation","label":""}],"html":"<p>יסוד foundation  תרג׳ ירוש׳ בר׳ ל׳ י״א: דעתיד למגדעא משתוייהון.</p>","notation":["ז׳"]},"41853":{"h":"מִשְׁתּוֹקָא","r":"KRU12229","alt":[],"source":"krupnik","glosses":[{"text":"silence","label":""}],"html":"<p>שתיקה silence  מגי׳ י״ח ע״א: מלה בסלע משתוקא בתרין.</p>","notation":["ז׳"]},"41854":{"h":"מִשְׁתּוּתָא","r":"KRU12230","alt":[],"source":"krupnik","glosses":[{"text":"wedding) feast","label":""}],"html":"<p>משתה (wedding) feast  איכ״ר א׳ ז׳: שבעה יומין דמשתותא.</p>","notation":["נ׳"]},"41855":{"h":"מַשְׁתֵּי","r":"KRU12231","alt":[],"source":"krupnik","glosses":[{"text":"web","label":""}],"html":"<p>. ארג web  שמו״ר פמ״ב: משתי בישתא אשתיתון.</p>","notation":["נ׳"]},"41856":{"h":"מִשְׁתִּי","r":"KRU12232","alt":["מִשְׁתְּיָא"],"source":"krupnik","glosses":[{"text":"drinking","label":""}],"html":"<p>שתיה drinking  תרג׳ יח׳ ל״ד י״ט: משתי שמשיכון; דהי״ב ט׳ כ׳ (כלי משקה): מאני משתיא.</p>","notation":[]},"41857":{"h":"מַשְׁתִּית","r":"KRU12233","alt":[],"source":"krupnik","glosses":[{"text":"foundation","label":""}],"html":"<p>יסוד foundation  ב״ר פע״ה: משתיתו ויסודו.</p>","notation":["נ׳"]},"41858":{"h":"מִשְׁתְּמוֹדַע","r":"KRU12235","alt":[],"source":"krupnik","glosses":[{"text":"acquaintance, friend","label":""}],"html":"<p>רֵע וידיד acquaintance, friend  תרג׳ תה׳ קמ״ב ה׳ (ואין לי מכיר): לית לי משתמודע.</p>","notation":["ז׳"]},"41859":{"h":"מֵת מֵת מִצְוָה","r":"KRU12238","alt":[],"source":"krupnik","glosses":[{"text":"a dead person whose relatives are unknown and whose burial is obligatory on everybody","label":"1"},{"text":"relations whom one is obliged to bury","label":"2"}],"html":"<p>1 מי שמת ואין קרוביו ידועים והכל חייבים לטפל בקבורתו a dead person whose relatives are unknown and whose burial is obligatory on everybody  ברכ׳ י״ט ע״א וע״ב: לאחותו הוא דאינו מטמא אבל מטמא הוא למת מצוה.\n2 קרוב מבני המשפחה ששאר הקרובים חייבים לטפל בקבורתו relations whom one is obliged to bury  מו״ק כ׳ ע״א: במה דברים אמורים בחמשה מתי מצוה אבל על אביו ואמו שבעה ושלשים.</p>","notation":["Marked biblical in source"]},"41860":{"h":"מָתָא","r":"KRU12239","alt":[],"source":"krupnik","glosses":[{"text":"place, town","label":""}],"html":"<p>מקום, עיר place, town  ב״מ ע״ה ע״ב: דביש ליה בהאי מתא ולא אזיל למתא אחריתי.</p>","notation":["נ׳"]},"41861":{"h":"מַתַּאי","r":"KRU12240","alt":[],"source":"krupnik","glosses":[{"text":"Matthew, a disciple of Jesus","label":""}],"html":"<p>אחד מתלמידי ישו הנוצרי Matthew, a disciple of Jesus  סנה׳ מ״ג ע״א (עפ״י קונטרס השמטות הש״ם): חמשה תלמידים היו לו לישו מתאי וכו׳.</p>","notation":[]},"41862":{"h":"מַתְאִים","r":"KRU12241","alt":[],"source":"krupnik","glosses":[{"text":"the central rib of a branch of palm-leaves","label":""}],"html":"<p>ראש הלולב המורכב משני עלים the central rib of a branch of palm-leaves  ירוש׳ סוכה פ״ג נ״ג ע״ג: נחלק המתאים כמי שנפרדו העלים.</p>","notation":["ז׳"]},"41863":{"h":"מַתְאִימוֹת","r":"KRU12242","alt":[],"source":"krupnik","glosses":[{"text":"molar teeth","label":""}],"html":"<p>השנים הטוחנות molar teeth  ספרא אמור פרק ו׳ פרשה ז׳: אין בודקין מן המתאימות ולפנים.</p>","notation":["Marked biblical in source"]},"41864":{"h":"מְתָאכְלָא","r":"KRU12243","alt":[],"source":"krupnik","glosses":[{"text":"string","label":""}],"html":"<p>מחרוזת string  ב״ב פ״ו ע״א: מתאכלי דתומי.</p>","notation":["ז׳"]},"41865":{"h":"מְתָארָא","r":"KRU12244","alt":[],"source":"krupnik","glosses":[{"text":"poker","label":""}],"html":"<p>אוד לגריפה poker  חג׳ ד׳ ע״ב: הות נקיטא מתארא בידה והוות קא שגרא ומחריא תנורא.</p>","notation":["ז׳"]},"41866":{"h":"מִתְבְּרָא","r":"KRU12246","alt":[],"source":"krupnik","glosses":[{"text":"breakers","label":""}],"html":"<p>משברי ים breakers  תרג׳ תה׳ מ״ב ח׳ (משבריך וגליך): מתברייך וגלילייך.</p>","notation":["ז׳"]},"41867":{"h":"מִתֵּג","r":"KRU12247","alt":[],"source":"krupnik","glosses":[{"text":"to bridle","label":"פיעל,"}],"html":"<p>פיעל, שם מתג ורסן to bridle  פסיק׳ זכור כ״ד ע״ב: הסוס הזה את ממתגו וכו׳.</p>","notation":[]},"41868":{"h":"מְתוּבְתָּא","r":"KRU12248","alt":[],"source":"krupnik","glosses":[{"text":"seat","label":""}],"html":"<p>מושב seat  תרג׳ שופ׳ ה׳ י״א: מתובת מוכסין.</p>","notation":["נ׳"]},"41869":{"h":"מַתְוֵי","r":"KRU12249","alt":[],"source":"krupnik","glosses":[{"text":"desire","label":""}],"html":"<p>תשוקה desire  תרג׳ יב״ע בר׳ ג׳ ט״ז (תשוקתך): מתויך.</p>","notation":["ז׳"]},"41870":{"h":"מִתּוֹךְ","r":"KRU12250","alt":[],"source":"krupnik","glosses":[{"text":"since, through, because of","label":""}],"html":"<p>מפני, על ידי, בסבת since, through, because of  ביצה י״ב ע״א: מתוך שהותרה הוצאה לצורך וכו׳; פס׳ נ׳ ע״ב: מתוך שלא לשמה בא לשמה.</p>","notation":["מה״י"]},"41871":{"h":"מָתוֹלָא","r":"KRU12251","alt":[],"source":"krupnik","glosses":[{"text":"poet","label":""}],"html":"<p>ממשל משלים poet  תרג׳ יב״ע במ׳ כ״א כ״ז (המושלים): מתוליא.</p>","notation":["ז׳"]},"41872":{"h":"מְתוּלָע","r":"KRU12252","alt":[],"source":"krupnik","glosses":[{"text":"wormy","label":""}],"html":"<p>שיש בו תולעים wormy  ב״ב פ״ו מ״ב: תאנים מקבל עליו עשר מתולעות למאה.</p>","notation":["ת׳"]},"41873":{"h":"מָתוּן","r":"KRU12253","alt":[],"source":"krupnik","glosses":[{"text":"considerate, careful","label":"1"},{"text":"name of an Amora","label":"2"}],"html":"<p>1  considerate, careful  אבות פ״א מ״א: הוו מתונים בדין.\n2 שם אמורא name of an Amora  ב״ק צ״ו ע״א: דא״ר מתון א״ר יהושע בן לוי.</p>","notation":[]},"41874":{"h":"מְתוּנָא","r":"KRU12254","alt":["מְתוּנְתָּא"],"source":"krupnik","glosses":[{"text":"moisture","label":""}],"html":"<p>טחב moisture  ב״ב י״ח ע״א: מתונתא קשה לכותל; שם י״ט ע״א: היזיקא דמתונא.</p>","notation":[]},"41875":{"h":"מְתוּרְגְּמָן","r":"KRU12255","alt":[],"source":"krupnik","glosses":[{"text":"interpreter","label":"1"},{"text":"translator (into Chaldaic or Greek) of the Biblical portion read at service","label":"2"}],"html":"<p>1 מליץ interpreter  איכ״ר א׳ י״ג: ויאמר וכו׳ למתורגמן ויאמר המתורגמן.\n2 מתרגם קריאת התורה בבית הכנסת לארמית או יונית translator (into Chaldaic or Greek) of the Biblical portion read at service  מגי׳ פ״ד מ״ד: לא יקרא למתורגמן יותר מפסוק אחד.</p>","notation":["ז׳"]},"41876":{"h":"מְתוֹרִין","r":"KRU12256","alt":[],"source":"krupnik","glosses":[{"text":"frontiers","label":""}],"html":"<p>גבולות frontiers  ויק״ר פכ״ז: הגיע למתורין שלו.</p>","notation":["ז״ר"]},"41877":{"h":"מְתוּשָׁע","r":"KRU12257","alt":[],"source":"krupnik","glosses":[{"text":"ninefold","label":""}],"html":"<p>פי תשעה ninefold  ירוש׳ שבי׳ פ״א ל״ג ע״ב: חשבון מתושע.</p>","notation":["ת׳"]},"41878":{"h":"מִתַּח","r":"KRU12258","alt":[],"source":"krupnik","glosses":[{"text":"to extend, to stretch","label":"פיעל,"},{"text":"to be stretched","label":"נִמְתַּח נפ׳, נתפ׳,"}],"html":"<p>פיעל, פירס, ריקע to extend, to stretch  מו״ק פ״א מ״ח: מסרגין את המטות וכו׳ ממתחין וכו׳.\nנִמְתַּח נפ׳, נתפ׳, נִתְמַתַּח נפרס ונתפשט to be stretched  סנה׳ ל״ח ע״א: נמתחו אבריו; תנח׳ חיי ג׳: והיו הולכין ומתמתחין.</p>","notation":[]},"41879":{"h":"מִתְחָא","r":"KRU12260","alt":[],"source":"krupnik","glosses":[{"text":"extension","label":"1"},{"text":"tent-pin","label":"2"},{"text":"bow-string","label":"3"}],"html":"<p>1 התפשטות extension  תרג׳ תה׳ י״ט ה׳ (קום): מתח ענינהון.\n2 יתד tent-pin  תרג׳ יב״ע שמ׳ ל״ח כ׳ (היתדות): מתחיא.\n3 מיתר הקשת bow-string  ויק״ר פ״ה: מתחי גירא.</p>","notation":["ז׳"]},"41880":{"h":"מַתְחֲלָא","r":"KRU12261","alt":[],"source":"krupnik","glosses":[{"text":"the calyx surrounding the date in its early stage","label":""}],"html":"<p>קליפת הגרעין the calyx surrounding the date in its early stage  כת׳ ע״ז ע״ב: מתחלא דדיקלא סומקא.</p>","notation":["ז׳"]},"41881":{"h":"מְתַחְתָּא","r":"KRU12262","alt":[],"source":"krupnik","glosses":[{"text":"stretching","label":""}],"html":"<p>מיתוח stretching  גיט׳ פ״ח ע״א: מתחתא דמגילתא.</p>","notation":["נ׳"]},"41882":{"h":"מַתְּיָא","r":"KRU12263","alt":[],"source":"krupnik","glosses":[{"text":"name of a Tannai","label":""}],"html":"<p>שם תנא name of a Tannai  אבות פ״ד מט״ו: ר׳ מתיא בן חרש אומר.</p>","notation":[]},"41883":{"h":"מְתִיבתָּא","r":"KRU12265","alt":[],"source":"krupnik","glosses":[{"text":"college, academy","label":"1"},{"text":"answer, argument","label":"2"}],"html":"<p>1 ישיבה, בית מדרש college, academy  ב״ב י״ב ע״ב: ריש מתיבתא.\n2 תשובה, ראיה answer, argument  ירוש׳ גיט׳ פ״ח מ״ט ע״ג: כל אילין מתיבתא דהוה ר׳ זעירא משיב.</p>","notation":["נ׳"]},"41884":{"h":"מַתְיָה","r":"KRU12266","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ ערלה פ״א ס׳ ע״ד: ר׳ מתיה מן דבתרתה.</p>","notation":[]},"41885":{"h":"מְתִיכְלָא","r":"KRU12267","alt":["מְתִיכְלְתָא"],"source":"krupnik","glosses":[{"text":"basin","label":""}],"html":"<p>כיור basin  תרג׳ איוב מ״א כ״ג (כמרקחה): היך מתיכלא; חול׳ מ״ו ע״ב: מתיכלתא דמיא פשורי.</p>","notation":["ז׳"]},"41886":{"h":"מְתִינָא","r":"KRU12269","alt":[],"source":"krupnik","glosses":[{"text":"deliberation","label":""}],"html":"<p>ישוב הדעת deliberation  ב״ר פס״ז: בא לו עשו במתינה.</p>","notation":["נ׳"]},"41887":{"h":"מְתִינוּת","r":"KRU12270","alt":[],"source":"krupnik","glosses":[{"text":"slow motion","label":""}],"html":"<p>אטיות slow motion  ב״ר פ״י: סיבבן דרך ארוכה ובמתינות.</p>","notation":["נ׳"]},"41888":{"h":"מְתִינְתָּא","r":"KRU12271","alt":[],"source":"krupnik","glosses":[{"text":"hope","label":""}],"html":"<p>תקוה, תוחלת hope  תרג׳ איוב י״ז ט״ו (ותקותי מי ישורנה): ומתינתי מן יסכינה.</p>","notation":["נ׳"]},"41889":{"h":"מְתִיק","r":"KRU12272","alt":[],"source":"krupnik","glosses":[{"text":"sweet","label":""}],"html":"<p>ערֵב, מתוק sweet  מגי׳ ו׳ ע״א: דמתיקי פירא.</p>","notation":["ת׳"]},"41890":{"h":"מְתִיקָה","r":"KRU12273","alt":[],"source":"krupnik","glosses":[{"text":"sweet taste, sweets","label":"1"},{"text":"relish","label":"2"}],"html":"<p>1 מותק, טעם מתוק, דבר מתוק sweet taste, sweets  ב״ק פ״ד ע״א: דבש וכל מיני מתיקה.\n2 לפתן relish  ב״מ פ״ז מ״א: מקום שנהגו וכו׳ לספק במתיקה יספק.</p>","notation":["נ׳"]},"41891":{"h":"מַתַּךְ","r":"KRU12275","alt":["מַתְּכָא"],"source":"krupnik","glosses":[{"text":"cast metal, molten image","label":""}],"html":"<p>יציקת מתכת, מסכה cast metal, molten image  תרג׳ מל״א ז׳ ט״ז (מוצק נחושת): מתך נחשא; דב׳ כ׳ י״ב (מסכה): מתכא.</p>","notation":[]},"41892":{"h":"מַתְכּוּלִיתָא","r":"KRU12276","alt":["מַתְכִּילְתָּא"],"source":"krupnik","glosses":[{"text":"relish","label":""}],"html":"<p>לפתן relish  פס׳ מ״ג ע״א: קריבו לי מתכילתא; שבת ע״ז ע״ב: מתכוליתא.</p>","notation":[]},"41893":{"h":"מַתֶּכֶת","r":"KRU12277","alt":[],"source":"krupnik","glosses":[{"text":"metal","label":""}],"html":"<p>סוג הדוממים המותכים באש metal  כל׳ פי״ג מ״ו: עץ המשמש את המתכת.</p>","notation":["נ׳"]},"41894":{"h":"מְתַל","r":"KRU12279","alt":[],"source":"krupnik","glosses":[{"text":"to compare","label":""},{"text":"to speak metaphorically","label":""},{"text":"to speak metaphorically","label":""},{"text":"to propound a riddle","label":""},{"text":"to be compared","label":""}],"html":"<p>1) השוה to compare  ירוש׳ דמ׳ פ״א כ״א ע״ד: מאן מתל לך עם תבליא. 2) דיבר במשלים to speak metaphorically  תרג׳ יח׳ י״ב כ״ב (ולא ימשלו אותו עוד): ולא ימתלון יתיה עוד. אַמְתֵּיל  אפ׳, 1) משל משלים to speak metaphorically  תרג׳ יח׳ כ״א ה׳ (ממשל משלים): ממתיל מתלין. 2) חד חידות to propound a riddle  תרג׳ שני אסת׳ א׳ ג׳: אמתיל לך תלתא מתלין. אִתְמְתַל אתפ׳, נשתוה to be compared  תרג׳ תה׳ כ״ח א׳ (ונמשלתי עם יורדי בור): ואתמתלית עם נחתי גובא. </p>","notation":["פ״י"]},"41895":{"h":"מְתַל²","r":"KRU12280","alt":["מְתַלָא"],"source":"krupnik","glosses":[{"text":"parable, byword","label":"1"}],"html":"<p>1 משל parable, byword  ירוש׳ דמ׳ פ״א כ״א ע״ד: דמתלין לה מתל בגלילא; סנה׳ פ״ד כ״ב ע״ב: מתלא אמר הוי ראש לשועלים ולא זנב לאריות.\n2 עי׳ אֲמַתְלָא. ירוש׳ כת׳ פ״ב כ״ו ע״ג: הביאה מתלא לדבריה. </p>","notation":[]},"41896":{"h":"מָתַן","r":"KRU12282","alt":[],"source":"krupnik","glosses":[{"text":"to lie over (for ripening)","label":""},{"text":"to wait","label":""},{"text":"to be slow, patient","label":""}],"html":"<p>היה מונח זמן רב to lie over (for ripening)  טהר׳ פ״ט מ״ה: המניח זיתים בכופש שימתנו וכו׳. הִמְתִּין הפ׳, 1) כנ״ל. מכש׳ פ״ו מ״ב: המעלה את האגודות וכו׳ לגג בשביל שימתינו. 2) חכה to wait  שקל׳ פ״ח מ״ה: ממתינים לו עד הערב. 3) היה מתון to be slow, patient  אדר״נ פ״א: שיהא אדם ממתין בדבריו ואל יהיה מקפיד וכו׳. </p>","notation":["פ״ע"]},"41897":{"h":"מַתְּנָא","r":"KRU12284","alt":[],"source":"krupnik","glosses":[{"text":"gift","label":"1"},{"text":"name of an Amora","label":"2"}],"html":"<p>1 מתנה gift  תרג׳ יב״ע בר׳ כ״ג י״א (נתתי לך): לך יהבית למתנא.\n2 שם אמורא name of an Amora  חול׳ מ״ב ע״ב: מתנא אמר שמואל.</p>","notation":["ז׳"]},"41898":{"h":"מִתְנָא","r":"KRU12285","alt":["מִתְנָה"],"source":"krupnik","glosses":[{"text":"rope","label":""}],"html":"<p>חבל rope  עיר׳ ל״ד ע״א: כוותא ומתנא; ב״ב פ״ט ע״א: קנה ומתנה.</p>","notation":[]},"41899":{"h":"מַתָּנָה","r":"KRU12286","alt":[],"source":"krupnik","glosses":[{"text":"sprinkling the blood on the altar","label":""}],"html":"<p>זריקת דם על המזבח sprinkling the blood on the altar  זבח׳ פ״ה מ״ג: ודמן טעון ארבע מתנות על ארבע קרנות.</p>","notation":["Marked biblical in source"]},"41900":{"h":"מַתְנֵי","r":"KRU12287","alt":["מַתנְיָין"],"source":"krupnik","glosses":[{"text":"teacher of the Mishnah","label":""}],"html":"<p>מלמד משנה teacher of the Mishnah  כת׳ ח׳ ע״ב: מקרי בניה דריש לקיש הוה ואמרי לה מתני בניה דריש לקיש הוה; ירוש׳ חג׳ פ״א ע״ו ע״ג: לא ספר ולא מתניין.</p>","notation":[]},"41901":{"h":"מַתַּנְתָּא","r":"KRU12289","alt":[],"source":"krupnik","glosses":[{"text":"donation","label":""}],"html":"<p>מתנה donation  ב״ב מ׳ ע״א: מתנתא טמירתא.</p>","notation":["נ׳"]},"41902":{"h":"מִתֵּק","r":"KRU12291","alt":[],"source":"krupnik","glosses":[{"text":"to sweeten, to season","label":"פיעל,"},{"text":"to become sweet","label":"הִתְמַתֵּק התפ׳,"}],"html":"<p>פיעל, הוסיף מתיקות ועריבות, תיבל to sweeten, to season  במ״ר פי״ג: חרדל צריך למתק.\nהִמְתִּיק הפ׳, ·– כנ״ל. שהש״ר ה׳ ט״ו: והמתיק להם הקב״ה את הדיבור. \nהִתְמַתֵּק התפ׳, נעשה מתוק וערב to become sweet  ירוש׳ ע״ז פ״ב מ״ב ע״א: שהמים וכו׳ מתמתקין.</p>","notation":[]},"41903":{"h":"מַתֵּק","r":"KRU12292","alt":[],"source":"krupnik","glosses":[{"text":"to suck","label":""}],"html":"<p>מצץ to suck  ע״ז י״ח ע״ב: טמש בהא ומתק בהא. אִתְמַתֵּק אתפ׳, עי׳ הִתְמַתֵּק. תרג׳ דהי״ב י״ג ה׳: לית איפשר דמתמתקן. </p>","notation":["פַעל"]},"41904":{"h":"מַתְקוּלְתָּא","r":"KRU12293","alt":[],"source":"krupnik","glosses":[{"text":"plummet","label":"1"}],"html":"<p>1 משקולת, אנך plummet  תרג׳ איוב ל״ח ה׳ (מי נטה עליה קו): מן מתח עלה מתקולתא.\n2 עי׳ מַתְקַל. פס׳ נ׳ ע״ב: שכר אשתו מתקולתא. </p>","notation":["נ׳"]},"41905":{"h":"מִתְקַל","r":"KRU12294","alt":[],"source":"krupnik","glosses":[{"text":"stumbling, offense","label":""}],"html":"<p>מכשול stumbling, offense  תרג׳ יש׳ ח׳ י״ד (צור מכשול): כיף מתקל.</p>","notation":["ז׳"]},"41906":{"h":"מַתְקַל","r":"KRU12295","alt":["מַתְקְלָא"],"source":"krupnik","glosses":[{"text":"weight","label":""}],"html":"<p>משקל weight  תרג׳ שמ׳ ל׳ ל״ד (בד בבד): מתקל במתקל; בכורות נ׳ ע״א: במתקלא דדינרא.</p>","notation":[]},"41907":{"h":"מְתַקַּנְתָּא","r":"KRU12296","alt":[],"source":"krupnik","glosses":[{"text":"firm solution","label":""}],"html":"<p>הלכה מתוקנת ומאוששת firm solution  יומא ע׳ ע״א: לא משכחת לה מתקנתא אלא או לר׳ אליעזר וכו׳.</p>","notation":["נ׳"]},"41908":{"h":"מַתְרוּתָא","r":"KRU12297","alt":[],"source":"krupnik","glosses":[{"text":"infusion","label":""}],"html":"<p>משרה infusion  תרג׳ במ׳ ו׳ ג׳ (משרת ענבים): מתרות עינבין.</p>","notation":["נ׳"]},"41909":{"h":"מִתְרַמְרְמוּתָא","r":"KRU12299","alt":[],"source":"krupnik","glosses":[{"text":"contempt","label":""}],"html":"<p>ביזוי contempt  תרג׳ תה׳ כ״ב ז׳ (ובזוי עם): מתרמרמותא דעממי.</p>","notation":["נ׳"]},"41910":{"h":"מְתָרַצְתָּא","r":"KRU12300","alt":[],"source":"krupnik","glosses":[{"text":"sustained version","label":""}],"html":"<p>גירסא נכונה sustained version  שבת קכ״א ע״ב: מאן נימא לן דהא מתרצתא היא דילמא משבשתא היא.</p>","notation":["נ׳"]},"41911":{"h":"נָא","r":"KRU12302","alt":[],"source":"krupnik","glosses":[{"text":"I","label":""}],"html":"<p>אני I  ירוש׳ בר׳ פ״ד ז׳ ע״א: ונא אמרית.</p>","notation":["מה״ג"]},"41912":{"h":"נָאגָא","r":"KRU12303","alt":[],"source":"krupnik","glosses":[{"text":"soot","label":""}],"html":"<p>פיח soot  איכ״ר ד׳ ח׳ (שחור): נאגא.</p>","notation":["ז׳"]},"41913":{"h":"נָאֶה","r":"KRU12305","alt":[],"source":"krupnik","glosses":[{"text":"handsome","label":""}],"html":"<p>יפה handsome  שבת קל״ג ע״ב: סוכה נאה.</p>","notation":["ת׳"]},"41914":{"h":"נֵאָה","r":"KRU12306","alt":[],"source":"krupnik","glosses":[{"text":"to decorate","label":"פיעל,"}],"html":"<p>פיעל, הידר וקישט to decorate  סוכה י׳ ע״א: לנאותה כשרה.</p>","notation":[]},"41915":{"h":"נִנְאָה","r":"KRU12307","alt":[],"source":"krupnik","glosses":[{"text":"to adorn oneself","label":"נפ׳, התפ׳,"}],"html":"<p>נפ׳, התפ׳, הִתְנָאֶה התקשט, התהדר to adorn oneself  נז׳ ב׳ ע״ב: אנאה לפניו; שבת קל״ג ע״ב: התנאה לפניו במצוות עשה לפניו סוכה נאה ולולב נאה.</p>","notation":[]},"41916":{"h":"נָאלָא","r":"KRU12309","alt":[],"source":"krupnik","glosses":[{"text":"furious","label":""}],"html":"<p>מטורף furious  שבת מ״ט ע״ב: ירוד נאלא.</p>","notation":["ת׳"]},"41917":{"h":"נָאנַאי","r":"KRU12310","alt":[],"source":"krupnik","glosses":[{"text":"dog","label":"1"},{"text":"a man’s name","label":"2"}],"html":"<p>1  dog  סוטה מ״ב ע״ב: וחד נאנאי.\n2  a man’s name  יב׳ ס״ו ע״ב: נאנאי בריה דרב יוסף.</p>","notation":[]},"41918":{"h":"נָאַף","r":"KRU12311","alt":[],"source":"krupnik","glosses":[{"text":"to cause illicit intercourse","label":"הִנְאִיף הפ׳,"}],"html":"<p>הִנְאִיף הפ׳, ·– סייע לזנות to cause illicit intercourse  שבוע׳ מ״ז ע״ב: אזהרה לעוקב אחר נואף מנין תלמוד לומר לא תנאף לא תנאיף.</p>","notation":[]},"41919":{"h":"נָאַץ","r":"KRU12312","alt":[],"source":"krupnik","glosses":[{"text":"to be insulted","label":"הִתְנָאֵץ התפ׳,"}],"html":"<p>הִתְנָאֵץ התפ׳, ·– נתקלל ונתגדף to be insulted  מדר תה׳ ע״ד: שמתחרף ומתנאץ בעולם.</p>","notation":[]},"41920":{"h":"נְאָקָה","r":"KRU12313","alt":[],"source":"krupnik","glosses":[{"text":"she-camel","label":""}],"html":"<p>נקבת הגמל she-camel  כל׳ פכ״ג מ״ב: אוכף של נאקה.</p>","notation":["Marked biblical in source"]},"41921":{"h":"נָאָתָא","r":"KRU12314","alt":[],"source":"krupnik","glosses":[{"text":"scurf","label":""}],"html":"<p>ארוכה שעל גבי המכה scurf  ב״ק פ״ה ע״ד: גרגותני נאתא כריכתא.</p>","notation":["נ׳"]},"41922":{"h":"נְבָארָא","r":"KRU12315","alt":[],"source":"krupnik","glosses":[{"text":"bast","label":""}],"html":"<p>סיב bast  שבת צ׳ ע״ב: דיקלא דחד נבארא.</p>","notation":["ז׳"]},"41923":{"h":"נְבַג","r":"KRU12316","alt":[],"source":"krupnik","glosses":[{"text":"to come to the surface","label":""}],"html":"<p>נתגלה to come to the surface  סנה׳ פ״ב ע״א: קברה והדר נבוג.</p>","notation":["פ״ע"]},"41924":{"h":"נִבְגָּא","r":"KRU12317","alt":[],"source":"krupnik","glosses":[{"text":"twig","label":""}],"html":"<p>ענף twig  פס׳ ע״ד ע״א: נבגא בר שתא.</p>","notation":["ז׳"]},"41925":{"h":"נִבּוּל","r":"KRU12322","alt":[],"source":"krupnik","glosses":[{"text":"disgrace), heathen festival","label":""}],"html":"<p>כנוי לחג של עכו״ם (disgrace), heathen festival  ב״ר פכ״ז: יום נבול של נילוס היה.</p>","notation":["ז׳"]},"41926":{"h":"נִבּוּל פֶּה","r":"KRU12323","alt":[],"source":"krupnik","glosses":[{"text":"lascivious talk","label":""}],"html":"<p>לשון שאינה נקיה lascivious talk  ויק״ר פכ״ד: ערות דבר זה נבול הפה.</p>","notation":[]},"41927":{"h":"נָבוֹלָא","r":"KRU12324","alt":[],"source":"krupnik","glosses":[{"text":"mean person","label":""}],"html":"<p>נבל mean person  ירוש׳ מכות פ״ב ל״א ע״ב: אית נבולין סגין וכו׳.</p>","notation":["ז׳"]},"41928":{"h":"נְבַח","r":"KRU12326","alt":[],"source":"krupnik","glosses":[{"text":"to bark","label":"1"},{"text":"to blab","label":"2"}],"html":"<p>1 חרץ הכלב לשונו to bark  פס׳ קי״ג ע״א: דלא נבח כלבא.\n2 פטפט to blab  מנ׳ ס״ג ע״א: מנבח נבוחי.</p>","notation":["פ״ע"]},"41929":{"h":"נַבֵּחַ","r":"KRU12327","alt":[],"source":"krupnik","glosses":[{"text":"to produce a dull sound","label":"2"}],"html":"<p>1 כנ״ל 1. ב״ר פנ״ט: קל כלביא מנבחין. \n2 השמיע קול צרוד to produce a dull sound  ביצה י״ד ע״א: תבלין נבוחי מנבח קליהו.</p>","notation":["פעל"]},"41930":{"h":"נבט","r":"KRU12328","alt":[],"source":"krupnik","glosses":[{"text":"to illumine","label":"הפ׳"}],"html":"<p>הפ׳ הִבִּיט ·– האיר to illumine  תרג׳ שני אס׳ א׳ ב׳: נשפך כמים ומביט לבית.</p>","notation":["Source marks no qal form"]},"41931":{"h":"נְבַט","r":"KRU12329","alt":[],"source":"krupnik","glosses":[{"text":"to sprout, to grow","label":""}],"html":"<p>צף וצמח to sprout, to grow  מו״ק י״ח ע״ב: הדר נבט.</p>","notation":["פ״ע"]},"41932":{"h":"נְבָט","r":"KRU12330","alt":[],"source":"krupnik","glosses":[{"text":"Nabataea","label":""}],"html":"<p>ארץ נביות Nabataea  תרג׳ יש׳ ס׳ ז׳ (אילי נביות): דכרי דנבט.</p>","notation":[]},"41933":{"h":"נבי","r":"KRU12331","alt":[],"source":"krupnik","glosses":[{"text":"to prophesy","label":"אתפ׳,"}],"html":"<p>אתפ׳, אִיתְנַבֵּי, אִינַּבֵּי התנבא וחזה to prophesy  מגי׳ י״ד ע״ב: ובמקום דקאי ירמיהו היכי מיתנביא איהי; ב״ב ט״ו ע״ב: אינבוי אינבי לאומות העולם.</p>","notation":["Source marks no qal form"]},"41934":{"h":"נְבִיאוּת","r":"KRU12332","alt":["נְבִיאוּתָא"],"source":"krupnik","glosses":[{"text":"prophecy","label":""}],"html":"<p>חזון ונבואה prophecy  עיר׳ ס׳ ע״ב: אין אילו אלא דברי נביאות; ב״ב ט״ו ע״ב: עיקר נביאותייהו.</p>","notation":[]},"41935":{"h":"נְבָיָה","r":"KRU12333","alt":[],"source":"krupnik","glosses":[{"text":"leaves","label":""}],"html":"<p>עלי האילן leaves  ע״ז מ״ח ע״ב: מפני שהנביה נושרת עליהן.</p>","notation":["נ׳"]},"41936":{"h":"נְבֵילָא","r":"KRU12336","alt":["נְבֵילְתָּא"],"source":"krupnik","glosses":[{"text":"carrion","label":""}],"html":"<p>נבלה, פגר carrion  תרג׳ ויק׳ כ״ב ח׳ (נבלה): נבילא; פס׳ קי״ג ע״א: פשוט נבילתא וכו׳.</p>","notation":[]},"41937":{"h":"נִבֵּל","r":"KRU12338","alt":[],"source":"krupnik","glosses":[{"text":"to make an animal ritually forbidden by unskillful slaughtering","label":"פיעל"}],"html":"<p>פיעל ·– שחט שלא כדין ועשה את הבהמה נבלה to make an animal ritually forbidden by unskillful slaughtering  נבלה תוס׳ ב״ק י׳ י׳: המוסר בהמה לטבח וניבלה.</p>","notation":[]},"41938":{"h":"נִבֵּל פִּיו","r":"KRU12339","alt":[],"source":"krupnik","glosses":[{"text":"to talk obscenely","label":""},{"text":"to be disgraced","label":""},{"text":"to become ritually forbidden by unskillful slaughtering","label":""}],"html":"<p>דיבר בלשון שאינה נקיה to talk obscenely  שבת ל״ג ע״א: כל המנבל פיו מעמיקים לו גיהנם. הִתְנַבֵּל התפ׳ 1) התנוול והתבזה to be disgraced  ירוש׳ יבמ׳ פי״ב י״ג ע״א: מי גרם לך להתנבל וכו׳. 2) נשחטה הבהמה שלא כדין ונעשתה נבלה to become ritually forbidden by unskillful slaughtering  חול׳ פ״ו מ״ב: השוחט ונתנבלה בידו. </p>","notation":[]},"41939":{"h":"נְבֵל","r":"KRU12340","alt":[],"source":"krupnik","glosses":[{"text":"to be soiled","label":""}],"html":"<p>הזדהם והתלכלך to be soiled  ירוש׳ כלא׳ פ״ט ל״ב ע״א: דלא ינבלון מאנוי.</p>","notation":["פ״ע"]},"41940":{"h":"נַבְעָה","r":"KRU12341","alt":[],"source":"krupnik","glosses":[{"text":"a plant","label":""}],"html":"<p>מין צמח a plant  ירוש׳ נד׳ פ״ז מ׳ ע״ב: במיני אפומלייא כגון נבעה וכו׳.</p>","notation":["נ׳"]},"41941":{"h":"נָבַר","r":"KRU12342","alt":[],"source":"krupnik","glosses":[{"text":"to dig","label":""}],"html":"<p>כרסם to dig  ב״ק י״ז ע״ב: נובר באשפה.</p>","notation":["פ״י"]},"41942":{"h":"נִבְרֶכֶת","r":"KRU12344","alt":[],"source":"krupnik","glosses":[{"text":"wash-pond","label":""}],"html":"<p>בריכת כובסים wash-pond  מו״ק פ״א מ״ו: עושין נברכת במועד.</p>","notation":["נ׳"]},"41943":{"h":"נִבְרֶשֶׁת","r":"KRU12345","alt":[],"source":"krupnik","glosses":[{"text":"lamp","label":""}],"html":"<p>מנורה, עששית lamp  יומא פ״ג מ״י: הילני אמו עשתה נברשת.</p>","notation":["נ׳"]},"41944":{"h":"נְגָאנָא","r":"KRU12346","alt":[],"source":"krupnik","glosses":[{"text":"cleft","label":""}],"html":"<p>חריץ cleft  ערכ׳ כ״ה ע״א: הנהו נגאני דארעא.</p>","notation":["ז׳"]},"41945":{"h":"נָגַב","r":"KRU12347","alt":[],"source":"krupnik","glosses":[{"text":"to be dry","label":""}],"html":"<p>היה יבש to be dry  ע״ז פ״ה מ״ד: כדי שיסתום ויגוב.</p>","notation":["פ״ע"]},"41946":{"h":"נִגֵּב","r":"KRU12348","alt":[],"source":"krupnik","glosses":[{"text":"to dry","label":"פיעל,"},{"text":"to go south","label":"הִנְגִּיב הפ׳, 2"}],"html":"<p>פיעל, ייבש to dry  ויק״ר פכ״ח: אדם מכבס כסותו בימות הגשמים כמה יגיעות הוא יגע עד שלא ינגבה.\nהִנְגִּיב הפ׳, 1 כנ״ל. חג׳ פ״ג מ״א (בבבלי): ומנגיב ומטביל. \nהִנְגִּיב הפ׳, 2 הלך דרומה, הדרים to go south  עיר׳ נ״ג ע״ב: הנגיב למפיבשת.</p>","notation":[]},"41947":{"h":"נִתְנַגֵּב","r":"KRU12349","alt":[],"source":"krupnik","glosses":[{"text":"to be dried up","label":"נתפ׳,"}],"html":"<p>נתפ׳, נתיבש to be dried up  ירוש׳ תענ׳ פ״ג ס״ז ע״א: וזרחה החמה ונתנגבה הארץ.</p>","notation":[]},"41948":{"h":"נִגֵּד","r":"KRU12350","alt":[],"source":"krupnik","glosses":[{"text":"to oppose","label":"פיעל,"}],"html":"<p>פיעל, התנגד to oppose  ילק׳ בר׳ כ״ג: לא זכה מנגדתו.</p>","notation":[]},"41949":{"h":"נְגַד","r":"KRU12351","alt":[],"source":"krupnik","glosses":[{"text":"to draw, to withdraw","label":""},{"text":"to lash","label":""},{"text":"to declare liable to lashes","label":""},{"text":"to extend","label":""},{"text":"to be lashed","label":""},{"text":"to die","label":""}],"html":"<p>1) משך, מנע to draw, to withdraw  גיט׳ ס״ח ע״ב: נגידו מיניה מיכליה. 2) הכה to lash  כת׳ ל״ג ע״ב: אילמלי נגדוה לחנניה מישאל ועזריה פלחו לצלמא. אַנְגֵּד  אפ׳, הלקה to declare liable to lashes  קיד׳ י״ב ע״ב: דרב מנגיד על דמקדש בשוקא. אִתְנְגַד, אִינְּגִּיד אתפ׳, 1) נמשך ונתארך to extend  תרג׳ יב״ע במ׳ כ״ה ח׳: איתנגיד פרזלא. 2) נלקה to be lashed  מכות י״א ע״ב: טוביה חטא וזיגוד מינגיד. 3) מת to die  ב״ב י׳ ע״ב: הלש ואינגיד. </p>","notation":["פ״י"]},"41950":{"h":"נָגְדָּא","r":"KRU12352","alt":[],"source":"krupnik","glosses":[{"text":"length","label":"1"},{"text":"distance","label":"2"},{"text":"river-course","label":"3"}],"html":"<p>1 אורך length  תרג׳ תה׳ כ״ג ו׳ (אורך ימים): נגדא דיומנא.\n2 מרחק distance  ב״ר פי״א: לנגדא את נגיד לי.\n3 זרם river-course  תרג׳ יש׳ מ״ד ד׳: נגדין דמיין.</p>","notation":["ז׳"]},"41951":{"h":"נִגְדָּא","r":"KRU12353","alt":[],"source":"krupnik","glosses":[{"text":"lashing","label":""}],"html":"<p>מלקות lashing  יומא כ״ג ע״א: פקיע – נגדא.</p>","notation":["ז׳"]},"41952":{"h":"נַגָּדָא","r":"KRU12354","alt":[],"source":"krupnik","glosses":[{"text":"leader","label":"1"},{"text":"dragger","label":"2"}],"html":"<p>1 מנהיג leader  ב״ק נ״ב ע״א: כד רגיז רעיא על ענא עביד לנגדא סמותא.\n2 סוחב האניה dragger  סוטה מ״ח ע״א: זמרא דנגדי.</p>","notation":["ז׳"]},"41953":{"h":"נְגָדָא","r":"KRU12355","alt":[],"source":"krupnik","glosses":[{"text":"name of a Tannai","label":""}],"html":"<p>שם תנא name of a Tannai  ויק״ר פכ״ה: מסתברא טעמא דנגדא.</p>","notation":[]},"41954":{"h":"נַגַּדְתָּא","r":"KRU12356","alt":[],"source":"krupnik","glosses":[{"text":"lashing","label":"2"}],"html":"<p>1 עי׳ מַשְׁכּוּכִית. ירוש׳ קיד׳ פ״א ס׳ ע״ב: מהו משכוכית וכו׳ ואית דאמרין נגדתא. \n2 מלקות lashing  פס׳ נ״ב ע״א: ממנין אנגדתא.</p>","notation":["נ׳"]},"41955":{"h":"נָגַהּ","r":"KRU12357","alt":[],"source":"krupnik","glosses":[{"text":"to revise","label":"הִגִּיהַּ הפ׳,"}],"html":"<p>הִגִּיהַּ הפ׳, ·– ·– קרא בספר לשם תקון טעיות to revise  בר׳ י״ג ע״א: בקורא להגיה.</p>","notation":[]},"41956":{"h":"נְגַהּ","r":"KRU12358","alt":[],"source":"krupnik","glosses":[{"text":"to shine","label":"1"},{"text":"to get dark","label":"2"}],"html":"<p>1 האיר to shine  יומא כ״ח ע״ב: אי הכי נגה להו טובא.\n2 החשיך היום to get dark  שבת י׳ ע״א: נגה לצלויי.</p>","notation":["פ״י"]},"41957":{"h":"נָגְהִי","r":"KRU12359","alt":[],"source":"krupnik","glosses":[{"text":"light","label":"1"},{"text":"evening","label":"2"}],"html":"<p>1 אור light  פס׳ ב׳ ע״א: נגהי נגהי ממש.\n2 ערב evening  פס׳ ד׳ ע״א: קרו נגהי ליליא.</p>","notation":["ז״ר"]},"41958":{"h":"נְגוּבָא","r":"KRU12360","alt":[],"source":"krupnik","glosses":[{"text":"dry","label":""}],"html":"<p>יבש dry  תרג׳ תה׳ ק״ב ז׳ (חרבות): ארעא נגובתא.</p>","notation":["ת׳"]},"41959":{"h":"נְגוּבָה","r":"KRU12361","alt":[],"source":"krupnik","glosses":[{"text":"dryness","label":""}],"html":"<p>יבושת dryness  חג׳ כ״ד ע״ב: וכי יש נגובה לקדש.</p>","notation":["נ׳"]},"41960":{"h":"נָגוֹד","r":"KRU12362","alt":["נָגוֹדָא"],"source":"krupnik","glosses":[{"text":"leader","label":""}],"html":"<p>מנהיג leader  ספרא אחרי פרק י״ב פרשה ט׳: לא המשנה נגוד אלא המעשה נגוד; תרג׳ דהי״א כ״ח ד׳ (בחר לנגיד): אתרעי לנגודא.</p>","notation":[]},"41961":{"h":"נַגְוָון","r":"KRU12363","alt":["נַגְוָותָא"],"source":"krupnik","glosses":[{"text":"islands, sea-districts","label":""}],"html":"<p>מדינות הים islands, sea-districts  תרג׳ יש׳ מ״ב ט״ו (איים); לנגוון; תה׳ ס״ה ו׳ (וים רחוקים): ונגוות ימא דרחיקין מן יבשתא.</p>","notation":[]},"41962":{"h":"נָגוֹטָא","r":"KRU12364","alt":[],"source":"krupnik","glosses":[{"text":"a spiced drink","label":""}],"html":"<p>משקה מבושם a spiced drink  ע״ז ל״ח ע״ב: נגוטא דחלא.</p>","notation":["ז׳"]},"41963":{"h":"נִגְזָל","r":"KRU12365","alt":[],"source":"krupnik","glosses":[{"text":"a complainant in a case of robbery","label":""}],"html":"<p>מי שהפסיד ע״י גזילה ותובע הפסדו a complainant in a case of robbery  שבועות פ״ז מ״א: אלו נשבעים ונוטלים השכיר והנגזל וכו׳.</p>","notation":["ז׳"]},"41964":{"h":"נָגַח","r":"KRU12366","alt":[],"source":"krupnik","glosses":[{"text":"to stir up to fighting","label":"הִגִּיחַ הפ׳,"}],"html":"<p>הִגִּיחַ הפ׳, ·– גירה לנגיחה to stir up to fighting  ב״ק פ״ד מ״ד: כי יגח ולא שיגיחוהו.</p>","notation":[]},"41965":{"h":"נַגְחָן","r":"KRU12367","alt":["נַגְחָנָא"],"source":"krupnik","glosses":[{"text":"a butter (ox)","label":""}],"html":"<p>מועד לנגיחה a butter (ox)  ב״ק מ״ו ע״א: המוכר שור לחבירו ונמצא נגחן; שם כ״ד ע״ב: תורא נגחנא.</p>","notation":[]},"41966":{"h":"נְגִיבָא","r":"KRU12368","alt":[],"source":"krupnik","glosses":[{"text":"dry","label":""}],"html":"<p>יבש dry  תרג׳ יב״ע שמ׳ י״ד כ״א (וישם את הים לחרבה): ושוי ית ימא נגיבא.</p>","notation":["ת׳"]},"41967":{"h":"נְגִידָא","r":"KRU12369","alt":[],"source":"krupnik","glosses":[{"text":"necromancy","label":""}],"html":"<p>דרישה אל המתים necromancy  גיט׳ נ״ז ע״א: אסקיה וכו׳ בנגידא.</p>","notation":["נ׳"]},"41968":{"h":"נְגִיחָה","r":"KRU12370","alt":[],"source":"krupnik","glosses":[{"text":"goring","label":""}],"html":"<p>נגיפה והדפה בקרן goring  כ״ק ב׳ ע״א: אין נגיחה אלא בקרן.</p>","notation":["נ׳"]},"41969":{"h":"נְגִינָר","r":"KRU12371","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ סוכה פ״א נ״ב ע״א: שהלך ר׳ יהושע בן קרחה אצל ר׳ יוחנן בן נורי לנגינר. </p>","notation":["שם מקום"]},"41970":{"h":"נְגִיעָה","r":"KRU12372","alt":[],"source":"krupnik","glosses":[{"text":"touching","label":""}],"html":"<p>מגע touching  כלה רבתי ב׳: נגיעה מביא לידי חימום.</p>","notation":["נ׳"]},"41971":{"h":"נְגִיפָה","r":"KRU12373","alt":[],"source":"krupnik","glosses":[{"text":"pushing","label":""}],"html":"<p>דחיפה והכאה pushing  מכי׳ משפ׳ גי״ב: בכלל נגיפה דחיה.</p>","notation":["נ׳"]},"41972":{"h":"נְגִירוּתָא","r":"KRU12374","alt":[],"source":"krupnik","glosses":[{"text":"forbearance","label":""}],"html":"<p>אורך אפים forbearance  תרג׳ משלי כ״ה ט״ו (בארך אפים): בנגירותא.</p>","notation":["נ׳"]},"41973":{"h":"נְגִישָׁה","r":"KRU12375","alt":[],"source":"krupnik","glosses":[{"text":"addressing, drawing near","label":""}],"html":"<p>קריבה addressing, drawing near  ירוש׳ סוטה פ״ח כ״ב ע״ב: מה נגישה שנאמר להלן בלשון הקודש.</p>","notation":["נ׳"]},"41974":{"h":"נָגַס","r":"KRU12377","alt":[],"source":"krupnik","glosses":[{"text":"to bite off","label":""}],"html":"<p>פרס פרוסה מן המאכל to bite off  טבו״י פ״ג מ״ו: טהור שנגס מן האוכל.</p>","notation":["פ״י"]},"41975":{"h":"נְגַס","r":"KRU12378","alt":[],"source":"krupnik","glosses":[{"text":"to eat, to dine","label":""}],"html":"<p>אכל to eat, to dine  ב״ר פצ״א: יתבין נגסון על פתורא דינאי מלכא.</p>","notation":["פ״י"]},"41976":{"h":"נָגַע","r":"KRU12379","alt":["נוֹגֵעַ בְּעֵדוּת"],"source":"krupnik","glosses":[{"text":"an interested witness","label":""}],"html":"<p>עד שיש לו נגיעה ויחס לדבר הנידון an interested witness  סנה׳ ל״ד ע״א: דמיחזי כנוגע בעדותו.</p>","notation":["Marked biblical in source"]},"41977":{"h":"נִתְנַגַּע","r":"KRU12380","alt":[],"source":"krupnik","glosses":[{"text":"to be afflicted with leprosy","label":"נתפ׳,"}],"html":"<p>נתפ׳, לקה בנגעים to be afflicted with leprosy  כר׳ פ״ב מ״ג: מצורע שנתנגע נגעים הרבה.</p>","notation":[]},"41978":{"h":"נִגְעָה","r":"KRU12381","alt":[],"source":"krupnik","glosses":[{"text":"hurt","label":""}],"html":"<p>גנאי hurt  במ״ר פי״ד: דבר כאן בנגעת יוסף דברים נער שהוא שוטה וכו׳.</p>","notation":["נ׳"]},"41979":{"h":"נִגֵּר","r":"KRU12382","alt":[],"source":"krupnik","glosses":[{"text":"to do carpenter’s work","label":"פיעל,"}],"html":"<p>פיעל, עשה מלאכת הנגר to do carpenter’s work  ילק׳ יהוש׳ זי: כלי נגרות היו בידם מנגרין וכו׳.</p>","notation":[]},"41980":{"h":"נְגַר","r":"KRU12383","alt":[],"source":"krupnik","glosses":[{"text":"to be prolonged","label":"1"},{"text":"to flow","label":"2"},{"text":"to saw","label":"3"}],"html":"<p>1 נמשך, ארך to be prolonged  תרג׳ מש׳ כ״ח כ״ז (יאריך ימים): ניגרון יומוי.\n2 זב, נזל to flow  תרג׳ איוב מ׳ כ״ג (יגיח ירדן אל פיהו): נגיר ירדנא לפומיה.\n3 ניסר במשור to saw  תרג׳ יש׳ י׳ ט״ו (היתפאר הגרזן על החוצב בו): אם יתרברב מסרא עם דנגיר ביה.</p>","notation":["פ״ע"]},"41981":{"h":"נַגֵּר","r":"KRU12384","alt":[],"source":"krupnik","glosses":[{"text":"to bolt","label":"פַעל,"}],"html":"<p>פַעל, סגר את הבריח to bolt  תרג׳ יונה ב׳ ז׳ (הארץ בריחיה בעדי): ארעא נגרת בתוקפהא עיל מיני.</p>","notation":[]},"41982":{"h":"נַגָּר","r":"KRU12385","alt":["נַגָּרָא"],"source":"krupnik","glosses":[{"text":"carpenter","label":"1"},{"text":"bolt","label":"2"}],"html":"<p>1 חרש עץ carpenter  תוס׳ ב״ק ו׳ כ״ה: נכנס לחנותו של נגר שלא ברשות יצתה בקעת וטפחה לו על פניו; תרג׳ יש׳ מ׳ י״ט (חרש עץ): פסלא נגרא.\n2 בריח bolt  ב״מ פ״ח מ״ז: בדלת ובנגר ובמנעול; תרג׳ שמ׳ כ״ו כ״ח (הבריח התיכון): נגרא מציעאה.</p>","notation":[]},"41983":{"h":"נַגַּר טוּרָא","r":"KRU12386","alt":[],"source":"krupnik","glosses":[{"text":"wood-cock","label":""}],"html":"<p>עוף הדוכיפת wood-cock  תרג׳ דב׳ י״ד י״ח (הדוכיפת): נגר טורא.</p>","notation":[]},"41984":{"h":"נַגָּרוּת","r":"KRU12387","alt":[],"source":"krupnik","glosses":[{"text":"carpenter’s trade","label":""}],"html":"<p>חרושת עץ carpenter’s trade  ירוש׳ ר״ה פ״א נ״ז ע״ב: לנגר שהיו לו כלי נגרות.</p>","notation":["נ׳"]},"41985":{"h":"נְגַּשׁ","r":"KRU12388","alt":[],"source":"krupnik","glosses":[{"text":"to gore","label":""}],"html":"<p>נגח to gore  תרג׳ יב״ע שמ׳ כ״א ל״ב (יגח שור): נגש תורא.</p>","notation":["פ״י"]},"41986":{"h":"נָדַב","r":"KRU12392","alt":[],"source":"krupnik","glosses":[{"text":"to be donated, to be dedicated","label":"נִדַּב נפ׳,"}],"html":"<p>נִדַּב נפ׳, ·– ניתן בתורת נדבה to be donated, to be dedicated  מגי׳ פ״א מ״י: כל שהוא נידר ונידב.</p>","notation":[]},"41987":{"h":"נִדְבָּה","r":"KRU12393","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ מגי׳ פ״א ע״א ע״ג: אשיין בר נדבה. </p>","notation":["שם איש"]},"41988":{"h":"נִדְבָּךְ","r":"KRU12394","alt":[],"source":"krupnik","glosses":[{"text":"layer","label":"1"},{"text":"a man’s name","label":"2"}],"html":"<p>1 שכבה של בנין, סואר layer  בר׳ פ״ב מ״ד: האומנין קורין בראש הנדבך.\n2 שם איש a man’s name  מנ׳ כ״ט ע״א: אשיאן בר נדבך.</p>","notation":["ז׳"]},"41989":{"h":"נִדְבָּכָה","r":"KRU12395","alt":[],"source":"krupnik","glosses":[{"text":"name of an idolatrous temple","label":""}],"html":"<p>שם בית עבודה זרה name of an idolatrous temple  ע״ז י״א ע״ב: נדבכה שבעכו.</p>","notation":[]},"41990":{"h":"נִדֵּד","r":"KRU12398","alt":[],"source":"krupnik","glosses":[{"text":"to keep oneself awake","label":"פיעל"},{"text":"to be shaken","label":"הִתְנַדֵּד הת׳"}],"html":"<p>פיעל היה ער בלילה to keep oneself awake  ב״ב י׳ ע״ב: שמנדדין שינה מעיניהם.\nהִתְנַדֵּד הת׳ נטלטל הנה והנה to be shaken  ילק׳ תקע״א: ובלבד שלא תהא מתנדדת.</p>","notation":["Used in: נִדֵּד שֵׁינָה מֵעֵינָיו"]},"41991":{"h":"נִדָּה","r":"KRU12399","alt":[],"source":"krupnik","glosses":[{"text":"to excommunicate","label":"פיעל"}],"html":"<p>פיעל ·– החרים to excommunicate  ע״ד פ״ה מ״ו: ונדוהו ומת בנדוי.</p>","notation":[]},"41992":{"h":"נִתְנַדָּה","r":"KRU12400","alt":[],"source":"krupnik","glosses":[{"text":"to be excommunicated","label":"נתפ׳,"}],"html":"<p>נתפ׳, הוחרם to be excommunicated  עד׳ פ״ה מ״ו: חס ושלום שעקביא נתנדה.</p>","notation":[]},"41993":{"h":"נִדּוּי","r":"KRU12401","alt":[],"source":"krupnik","glosses":[{"text":"excommunication","label":""}],"html":"<p>חרם ושמתא excommunication  בר׳ י״ט ע״א: אלמלי חוני אתה גוזרני עליך נדוי.</p>","notation":["ז׳"]},"41994":{"h":"נַדּוֹנָא","r":"KRU12402","alt":[],"source":"krupnik","glosses":[{"text":"a species of locust","label":""}],"html":"<p>מין ארבה a species of locust  תרג׳ יב״ע ויק׳ י״א כ״ב (החגב): נדונא.</p>","notation":["ז׳"]},"41995":{"h":"נְדוּנְיָא","r":"KRU12403","alt":[],"source":"krupnik","glosses":[{"text":"dowry, a bride’s outfit","label":""}],"html":"<p>מוהר ומתן dowry, a bride’s outfit  כת׳ נ״ד ע״א: נדוניא לברת וכו׳.</p>","notation":["ז׳"]},"41996":{"h":"נִדּוּת","r":"KRU12404","alt":[],"source":"krupnik","glosses":[{"text":"menstruation","label":""}],"html":"<p>מעמד הנדה menstruation  שבת י״ג ע״א: בימי נדותך וכו׳ אפילו באצבע קטנה לא נגע בי.</p>","notation":["נ׳"]},"41997":{"h":"נְדֵי","r":"KRU12405","alt":[],"source":"krupnik","glosses":[{"text":"to be excommunicated","label":""},{"text":"to sprinkle","label":""},{"text":"to throw","label":""}],"html":"<p>1) היה משומת ומנודה to be excommunicated  נד׳ ז׳ ע״א: נדינא ממך וכו׳ משמתנא ממך. 2) הזה, זרק to sprinkle  תרג׳ מל״ב ט׳ ל״ג (ויז): ונדא. אַדֵּי  אפ׳, 1) כנ״ל 2. תרג׳ שמ׳ י״ב כ״ב (והגעתם אל המשקוף): ותדון לשקפא. 2) זרק והשליך to throw  סנה׳ ז׳ ע״א: אדייה לגזיזיה. </p>","notation":["פעו״י"]},"41998":{"h":"נַדְיָין","r":"KRU12406","alt":[],"source":"krupnik","glosses":[{"text":"a species of locust","label":""}],"html":"<p>מין ארבה a species of locust  ספרא שמיני פרשה ג׳ פרק ה׳: חגב – נדיין.</p>","notation":["ז׳"]},"41999":{"h":"נִדְיָין","r":"KRU12407","alt":[],"source":"krupnik","glosses":[{"text":"wash-pond","label":""}],"html":"<p>בריכת כובסים wash-pond  ב״ב י״ט ע״א: מחמצן וכו׳ נדיין.</p>","notation":["ז׳"]},"42000":{"h":"נדירא","r":"KRU12408","alt":[],"source":"krupnik","glosses":[{"text":"fugitive","label":""}],"html":"<p>פליט fugitive  ירוש׳ שבת פ״ד ז׳ ע״א: נדיריא דאשקלון וכו׳ מקצתן בים ומקצתן ביבשה.</p>","notation":["ז׳","Source emendation: נְדִידָא"]},"42001":{"h":"נָדָל","r":"KRU12409","alt":[],"source":"krupnik","glosses":[{"text":"centipede","label":""}],"html":"<p>מין בעל חי מרבה רגלים centipede  מקואות פ״ה מ״ג: מעין שהוא משוך כנדל.</p>","notation":["ז׳"]},"42002":{"h":"נִדְמֶה","r":"KRU12410","alt":[],"source":"krupnik","glosses":[{"text":"a lamb looking like a kid and vice versa","label":""}],"html":"<p>עז הדומה לכשב ולהפך a lamb looking like a kid and vice versa  חול׳ ל״ח ע״ב: או כשב פרט לכלאים או עז פרט לנדמה.</p>","notation":["ז׳"]},"42003":{"h":"נִדְנֵד","r":"KRU12411","alt":[],"source":"krupnik","glosses":[{"text":"to shake, to be rocked","label":""}],"html":"<p>הניע והניד to shake, to be rocked  ב״ר פנ״ג: לא נדנדה עריסה תחלה אלא בביתו של אברהם אבינו.</p>","notation":["פ״י"]},"42004":{"h":"נִתְנַדְנֵד","r":"KRU12412","alt":[],"source":"krupnik","glosses":[{"text":"to be moved","label":"נתפ׳,"}],"html":"<p>נתפ׳, נע וזע to be moved  שמו״ר פ״כ: נתנדנד הארון.</p>","notation":[]},"42005":{"h":"נִדְנוּד","r":"KRU12413","alt":[],"source":"krupnik","glosses":[{"text":"moving about","label":"1"},{"text":"propensity","label":"2"}],"html":"<p>1 נדידה ממקום למקום moving about  ב״ר פל״ט: נדנוד אחר נדנוד טלטול אחר טלטול.\n2 נטיה קלה propensity  פס׳ נ׳ ע״ב: בכל מקום שיש שם נדנוד עבירה.</p>","notation":["ז׳"]},"42006":{"h":"נָדַף","r":"KRU12414","alt":[],"source":"krupnik","glosses":[{"text":"to spread (of odours)","label":""}],"html":"<p>נתפשט הריח to spread (of odours)  ב״ר פל״ט: היה ריחו נודף.</p>","notation":["Marked biblical in source"]},"42007":{"h":"נָדַר","r":"KRU12415","alt":[],"source":"krupnik","glosses":[{"text":"to be made subject of a vow","label":"נִדַּר נפ׳,"},{"text":"to put a person under the influence of a vow; to forbid","label":"הִדִּיר הפ׳,"}],"html":"<p>נִדַּר נפ׳, ·– נערך להקדש בתורת נדר to be made subject of a vow  ערכ׳ פ״א מ״א: נודרים ונידרים.\nהִדִּיר הפ׳, חייב ואסר בתורת נדר to put a person under the influence of a vow; to forbid  דמ׳ פ״ד מ״ב: המדיר את חבירו שיאכל אצלו.</p>","notation":[]},"42008":{"h":"נַדְרָן","r":"KRU12416","alt":[],"source":"krupnik","glosses":[{"text":"one wont to make vows","label":""}],"html":"<p>מהיר לנדרים one wont to make vows  ילק׳ שמואל קמ״ג: נדרן הוא קדם עד שלא ידור ואמור לו וכו׳.</p>","notation":["ת׳"]},"42009":{"h":"נדרשיר","r":"KRU12417","alt":[],"source":"krupnik","glosses":[{"text":"checkers","label":""}],"html":"<p>שחוק השַך, אישקוקי checkers  כת׳ ס״א ע״ב: דמיטללא בגורייתא קטנייתא ונדרשיר (ובערוך כנכון): נרדשיר.</p>","notation":["ז׳","Source emendation: נַרְדְּשִׁיר"]},"42010":{"h":"נָהַג","r":"KRU12418","alt":[],"source":"krupnik","glosses":[{"text":"to apply, to be wont to","label":""},{"text":"to drive","label":""},{"text":"to lead","label":""},{"text":"to introduce a custom","label":""},{"text":"to conduct o. s.","label":""},{"text":"to be conducted","label":""}],"html":"<p>היה רגיל לעשות, ליעשות to apply, to be wont to  פ״ד פס׳ מ״א: מקום שנהגו וכו׳; מגי׳ ו׳ ע״ב: מצוות שנוהגות וכו׳. הִנְהִיג הפ׳, 1) עי׳ הִתְנַהֵג 1. סוטה י״ג ע״א: הנהיג עצמו ברבנות. 2) נהל ומשך בבהמה to drive  ב״מ פ״א מ״ב: אחד רוכב ואחד מנהיג. 3) נהל, עמד בראש to lead  סנה׳ צ״ב ע״א: פרנס המנהיג את הצבור בנחת. 4) קבע לחוק ומנהג to introduce a custom  בר׳ י״ט ע״א: הנהיג את בני רומי להאכילן גדיים מקולסים וכו׳. הִתְנַהֵג התפ׳, 1) התיחס זה לזה to conduct o. s.  ספרי דב׳ שכ״ג: התנהגו זה את זה וכו׳. 2) היה מונהג, התנהל to be conducted  ירוש׳ ב״ק פ״ו ה׳ ע״ג: רוח שהעולם מתנהג בו. </p>","notation":["Marked biblical in source"]},"42011":{"h":"נִהוּג","r":"KRU12419","alt":[],"source":"krupnik","glosses":[{"text":"leading","label":""}],"html":"<p>הנהגה והנהלה leading  מכי׳ בשלח: ולא נחם – אין נחום זה אלא נהוג.</p>","notation":["ז׳"]},"42012":{"h":"נַהֲוַונְדְּ","r":"KRU12420","alt":[],"source":"krupnik","glosses":[{"text":"a Median town","label":""}],"html":"<p>עיר בארץ מדי a Median town  קיד׳ ע״ב ע״א: נהוונד וחברותיה.</p>","notation":[]},"42013":{"h":"נְהוֹרַאי","r":"KRU12422","alt":[],"source":"krupnik","glosses":[{"text":"name of Tannaim and Amoraim","label":"1"},{"text":"a woman’s name","label":"2"}],"html":"<p>1 שם תנאים ואמורים name of Tannaim and Amoraim  נז׳ פ״ט מ״ה: ר׳ נהוראי; חול׳ נ״ה ע״ב: פריש ר׳ נהוראי משמיה דשמואל.\n2 שם אשה a woman’s name  ירוש׳ בר׳ פ״ג ו׳ ע״א: נהוראי אחתיה דר׳ יהודה נשיאה.</p>","notation":[]},"42014":{"h":"נְהוֹרִיתָא","r":"KRU12423","alt":[],"source":"krupnik","glosses":[{"text":"blinding","label":"1"},{"text":"a woman’s name","label":"2"}],"html":"<p>1 סנורים blinding  ב״מ ע״ח ע״ב: הבריקה – נהוריתא.\n2 שם אשה a woman’s name  תרג׳ אס׳ ב׳ ט׳: בתלת בשבתא נהוריתא.</p>","notation":["נ׳"]},"42015":{"h":"נהי","r":"KRU12424","alt":[],"source":"krupnik","glosses":[{"text":"to assemble","label":"אִתְנְהֵי אתפ׳,"}],"html":"<p>אִתְנְהֵי אתפ׳, התאסף to assemble  תרג׳ ירמ׳ ג׳ י״ז (ונקוו): ויתנהון.</p>","notation":["Source marks no qal form"]},"42016":{"h":"נְהִי","r":"KRU12425","alt":[],"source":"krupnik","glosses":[{"text":"granted, admitted","label":""}],"html":"<p>נניח granted, admitted  יב׳ ס״א ע״א: נהי דמיעטינהו קרא מאטמויי באהל וכו׳ ממגע ומשא מי מיעטינהו קרא.</p>","notation":[]},"42017":{"h":"נְהִילַאי","r":"KRU12426","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  תענ׳ ו׳ ע״א: אמר רב נהילאי בר אידי אמר שמואל וכו׳.</p>","notation":[]},"42018":{"h":"נְהִימָה","r":"KRU12427","alt":[],"source":"krupnik","glosses":[{"text":"cooing","label":""}],"html":"<p>קול המיה cooing  פסיק״ר פכ״א: הנהימה שנהמתם לפני.</p>","notation":["נ׳"]},"42019":{"h":"נְהִיקָא","r":"KRU12428","alt":[],"source":"krupnik","glosses":[{"text":"braying","label":""}],"html":"<p>קול נאקה braying  תרג׳ יב״ע בר׳ ל׳ ט״ז: קל נהיקיה דחמרא.</p>","notation":["נ׳"]},"42020":{"h":"נְהַל","r":"KRU12429","alt":[],"source":"krupnik","glosses":[{"text":"to sift","label":""}],"html":"<p>ניפה בכברה to sift  ביצה כ״ט ע״ב: נהלא קמחא.</p>","notation":["פ״י"]},"42021":{"h":"נִהֵם","r":"KRU12430","alt":[],"source":"krupnik","glosses":[{"text":"to coo","label":"פיעל,"}],"html":"<p>פיעל, המה כיונה to coo  בר׳ ג׳ ע״א: מנהמת כיונה.</p>","notation":[]},"42022":{"h":"נַהֲמָא","r":"KRU12431","alt":[],"source":"krupnik","glosses":[{"text":"bread","label":""}],"html":"<p>לחם bread  ביצה ט״ז ע״א: בבלאי טפשאי דאכלי נהמא בנהמא.</p>","notation":["ז׳"]},"42023":{"h":"נַהֲמוּתָא","r":"KRU12432","alt":[],"source":"krupnik","glosses":[{"text":"roaring","label":""}],"html":"<p>שאגה roaring  תרג׳ תה׳ ל״ב ג׳ (בשאגתי): בנהמותי.</p>","notation":["נ׳"]},"42024":{"h":"נֶהְפְּכָנוּתָא","r":"KRU12434","alt":[],"source":"krupnik","glosses":[{"text":"perversity","label":""}],"html":"<p>הפכפכנות perversity  תרג׳ מש׳ א׳ ל״ב (משובת פתאים): נהפכנותא דשברי.</p>","notation":["נ׳"]},"42025":{"h":"נָהַר","r":"KRU12435","alt":[],"source":"krupnik","glosses":[{"text":"to enlighten","label":"הִנְהִיר הפ׳,"}],"html":"<p>הִנְהִיר הפ׳, ·– האיר to enlighten  עיר׳ י״ג ע״ב: שמנהיר עיני חכמים.</p>","notation":[]},"42026":{"h":"נְהַר","r":"KRU12436","alt":[],"source":"krupnik","glosses":[{"text":"to shine","label":"1"},{"text":"to remember","label":"2"}],"html":"<p>1 האיר to shine  פסיק׳ איכה קכ״ג ע״א: מרי ינהור דינא קדמך.\n2 נזכר to remember  ירוש׳ מגי׳ פ״א ע״ד ע״ב: נהיר את כד הוינן קיימין וכו׳.</p>","notation":["פ״ע"]},"42027":{"h":"נַהֵר","r":"KRU12437","alt":[],"source":"krupnik","glosses":[{"text":"to be brightened","label":""}],"html":"<p>כנ״ל 1. תרג׳ ירוש׳ שמ׳ י״ד כ׳: נהור מנהר על ישראל. אַנְהַר  אפ׳, 1) עי׳ נְהַר 1. סוטה ו׳ ע״א: אנהר לן עיינין. 2) עי׳ נְהַר 2. ירוש׳ פאה פ״ג י״ז ע״ד: ואנהר ר׳ אימי וחזר עובדא. אִתְנְהַר אתפ׳, הואר to be brightened  תרג׳ יב״ע בר׳ ג׳ ז׳ (ותפקחנה עיני שניהם): ואתנהרן עיני תרוייהון. </p>","notation":["פַעל"]},"42028":{"h":"נַהֲרָא","r":"KRU12438","alt":[],"source":"krupnik","glosses":[{"text":"river","label":"1"},{"text":"light","label":"2"}],"html":"<p>1 נהר, נחל river  חול׳ י״ח ע״ב: נהרא נהרא ופשטיה.\n2 אור light  תרג׳ מש׳ ד׳ י״א (הולך ואור): דאזיל נהריה.</p>","notation":["ז׳"]},"42029":{"h":"נְהַרְבֵּיל","r":"KRU12439","alt":["נְהַרְדְּעָא"],"source":"krupnik","glosses":[{"text":"names of towns in Babylonia","label":""}],"html":"<p>שמות ערים בבבל names of towns in Babylonia  חול׳ קל״ו ע״א: ר׳ אסי מנהרביל; סנה׳ י״ז ע״ב: דיינא דנהרדעא.</p>","notation":[]},"42030":{"h":"נוּ","r":"KRU12440","alt":[],"source":"krupnik","glosses":[{"text":"he, it","label":""}],"html":"<p>הוא, היא he, it  ירוש׳ נ״ז פ״ג נ״ב ע״ד: היי די נו כולל והיי די נו מונה.</p>","notation":["מה״ג"]},"42031":{"h":"נוֹא","r":"KRU12441","alt":[],"source":"krupnik","glosses":[{"text":"beauty","label":""}],"html":"<p>יופי, נוי beauty  קהל״ר ב׳ י״ב: והוא נואו.</p>","notation":["ז׳"]},"42032":{"h":"נְוַאי","r":"KRU12442","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  תוס׳ צוק׳ שבי׳ ד׳ ח׳: תחום נואי. </p>","notation":["שם מקום"]},"42033":{"h":"נוּב","r":"KRU12443","alt":[],"source":"krupnik","glosses":[{"text":"to be fluent","label":"הֵנִיב הפ׳,"}],"html":"<p>הֵנִיב הפ׳, ·– היה שוטף to be fluent  ויק״ר פט״ז: אם הניבו וכו׳.</p>","notation":[]},"42034":{"h":"נוּגְבָא","r":"KRU12444","alt":[],"source":"krupnik","glosses":[{"text":"dryness","label":""}],"html":"<p>יבושת dryness  תרג׳ איוב ל׳ ל׳ (ועצמי חרה מני חורב): וגרמי חרך מן נוגבא.</p>","notation":["ז׳"]},"42035":{"h":"נוֹגַהּ","r":"KRU12446","alt":[],"source":"krupnik","glosses":[{"text":"the planet Venus","label":""}],"html":"<p>אחד מכוכבי לכת the planet Venus  פסיק״ר פ״כ: כוכב זה האיש ונוגה זו האשה.</p>","notation":["Marked biblical in source"]},"42036":{"h":"נוּד","r":"KRU12449","alt":[],"source":"krupnik","glosses":[{"text":"to be unsteady","label":""},{"text":"to shake (the head)","label":""}],"html":"<p>היה נע ונד to be unsteady  כת׳ ט״ו ע״א: ניידי וכו׳ קביעי. אָנֵיד  אפ׳, הניע to shake (the head)  סנה׳ צ״ה ע״א: ומניד ברישיה. </p>","notation":["פ״ע"]},"42037":{"h":"נוֹדִיִין","r":"KRU12450","alt":[],"source":"krupnik","glosses":[{"text":"a superior sort of olives","label":""}],"html":"<p>מיני זיתים משובחים a superior sort of olives  ירוש׳ פאה פ״ז כ׳ ע״א: דרכן ליבחן בנודיין.</p>","notation":["ז״ר"]},"42038":{"h":"נָוָה","r":"KRU12452","alt":[],"source":"krupnik","glosses":[{"text":"to adorn oneself","label":"נִנְוָה נפ׳,"}],"html":"<p>נִנְוָה נפ׳, ·– נתקשט to adorn oneself  מכי׳ בשלח שירה ג׳: אנווה לפניו.</p>","notation":[]},"42039":{"h":"נִתְנַוָּה","r":"KRU12453","alt":[],"source":"krupnik","glosses":[{"text":"to be vain of","label":"נתפ׳,"}],"html":"<p>נתפ׳, נתפאר ונתגדר to be vain of  סוטה פ״א מ״ח (בירושלמי): אבשלום נתנוה בשערו.</p>","notation":[]},"42040":{"h":"נָוֶה","r":"KRU12454","alt":[],"source":"krupnik","glosses":[{"text":"handsome","label":""}],"html":"<p>יפה, נאה handsome  נז׳ פ״א מ״א: אהא נוה.</p>","notation":["ת׳"]},"42041":{"h":"נָוֶה²","r":"KRU12455","alt":["נוהא"],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>בארץ ישראל name of a place in Palestine  ויק״ר פ״ג: חלמיש לנוה; שם פל״ד: ר׳ שילה דנוהא.</p>","notation":[]},"42042":{"h":"נוֹהַג","r":"KRU12456","alt":["בְּנוֹהַג שֶׁבָּעוֹלָם"],"source":"krupnik","glosses":[{"text":"ordinarily, naturally","label":""}],"html":"<p>מנהג העולם כך הוא ordinarily, naturally  ירוש׳ בר׳ פ״א ב׳ ע״ד: בנוהג שבעולם אדם מותח אהל וכו׳.</p>","notation":["ז׳"]},"42043":{"h":"נָוֶוה","r":"KRU12457","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>בארץ ישראל name of a place in Palestine  רות רבה ב׳ י׳: ר׳ שילא דנווה.</p>","notation":["שם מקום"]},"42044":{"h":"נְוָוטִי","r":"KRU12458","alt":[],"source":"krupnik","glosses":[{"text":"Nabataean","label":""}],"html":"<p>איש ארץ נביות Nabataean  ב״ר פמ״ח: בדמות נווטי וכו׳ בדמות ערבי.</p>","notation":["ת׳"]},"42045":{"h":"נַוְוטִים","r":"KRU12459","alt":[],"source":"krupnik","glosses":[{"text":"seamen","label":""}],"html":"<p>מַלחים, יורדי הים seamen  ב״ר פי״ב: מלך ב״ו עושה ספינה וכו׳ ואח״כ הוא מעמיד עליה נווטים.</p>","notation":["ז״ר"]},"42046":{"h":"נִוּוּל","r":"KRU12460","alt":[],"source":"krupnik","glosses":[{"text":"contemptibility","label":""}],"html":"<p>נבלות ושפלות contemptibility  תנח׳ וישב א׳: להודיע נוולם.</p>","notation":["ז׳"]},"42047":{"h":"נְוַול","r":"KRU12461","alt":["נַוְולָא"],"source":"krupnik","glosses":[{"text":"loom","label":""}],"html":"<p>כסא אורג loom  ירוש׳ ב״ב פ״ב י״ג ע״ב: מסמרא דנווליה; שם: חד נוול.</p>","notation":[]},"42048":{"h":"נַוְולָא","r":"KRU12462","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  פ״מ ס״ז ע״א: את ונוולא אחי. </p>","notation":["שם איש"]},"42049":{"h":"נוון","r":"KRU12463","alt":[],"source":"krupnik","glosses":[{"text":"Thebes in Egypt","label":""}],"html":"<p>עיר במצרים Thebes in Egypt  פסיק״ר י״ז: נוון אלכסנדרי.</p>","notation":["Source emendation: נוֹא"]},"42050":{"h":"נוּז","r":"KRU12464","alt":[],"source":"krupnik","glosses":[{"text":"to twist, to twine, to weave","label":""}],"html":"<p>טוה, ארג, שזר to twist, to twine, to weave  ירוש׳ כלא׳ פ״ט ל״ב ע״ד: לנוז מותר.</p>","notation":["פ״י"]},"42051":{"h":"נוּחַ","r":"KRU12465","alt":[],"source":"krupnik","glosses":[{"text":"to be rested","label":"נִנּוֹחַ נפ׳,"}],"html":"<p>נִנּוֹחַ נפ׳, בא לידי מנוחה to be rested  שהש״ר ז׳ ה׳: והגליות באות ונינוחות.</p>","notation":["Marked biblical in source"]},"42052":{"h":"נוּחַ²","r":"KRU12466","alt":[],"source":"krupnik","glosses":[{"text":"to rest","label":""},{"text":"to die","label":""},{"text":"to quiet","label":""},{"text":"to put down","label":""},{"text":"to be laid down","label":""},{"text":"to be satisfactory","label":""}],"html":"<p>1) היה שרוי במנוחה to rest  תרג׳ בר׳ ב׳ ג׳ (שבת מכל מלאכתו): נח מכל עיבידתיה. 2) מת to die  כת׳ ק״ד ע״א: נח נפשיה דרבי. אַנַּח אתפ׳, 1) הרגיע to quiet  בר׳ כ״ח ע״ב: לאנוחי דעתיה דר׳ יוסף. 2) הניח to put down  כת׳ מ״ז ע״ב: אנוחי ננחינהו. אִתְנַיַח, אִתְנַח אתפ׳, 1) נוּחַ 1. תרג׳ יב״ע ויק׳ כ״ו ל״ה (תשבת): תתנייח. 2) הונח to be laid down  ב״ב י״ד ע״ב: דמתנח ליה. 3) היה רצוי to be satisfactory  קיד׳ מ״ה ע״ב: איתנוחי איתנחא ליה. </p>","notation":["פ״ע"]},"42053":{"h":"נוֹחַ","r":"KRU12467","alt":[],"source":"krupnik","glosses":[{"text":"pleased","label":"1"},{"text":"easy","label":"2"},{"text":"good, better (for)","label":"3"}],"html":"<p>1 מרוצה pleased  אב׳ פ״ג מ״י: שרוח הבריות נוחה הימנו.\n2 קל easy  אבות פ״ה מי״א: נוח לכעוס וקשה לרצות.\n3 טוב, מוטב good, better (for)  עיר׳ י״ג ע״ב: נוח לו לאדם שלא נברא יותר משנברא.</p>","notation":["Marked biblical in source"]},"42054":{"h":"נוט","r":"KRU12470","alt":[],"source":"krupnik","glosses":[{"text":"to scare","label":"אָנֵיט אפ׳,"}],"html":"<p>אָנֵיט אפ׳, החריד to scare  תרג׳ יב״ע ויק׳ כ״ו ו׳ (ואין מחריד): ולית דמניט.</p>","notation":["Source marks no qal form"]},"42055":{"h":"נוֹטִי","r":"KRU12471","alt":[],"source":"krupnik","glosses":[{"text":"remark","label":""}],"html":"<p>הערה remark  ירוש׳ מעש״ש פ״ב נ״ג ע״ג: והן נוטי נוטימי.</p>","notation":["נ׳"]},"42056":{"h":"נְוָטָיָיה","r":"KRU12472","alt":[],"source":"krupnik","glosses":[{"text":"Nabataean","label":""}],"html":"<p>איש ארץ נביות Nabataean  ב״ר פמ״ה: נוטייה.</p>","notation":["ת׳"]},"42057":{"h":"נוֹטִימִי","r":"KRU12473","alt":[],"source":"krupnik","glosses":[{"text":"remarkable","label":""}],"html":"<p>ראוי לתשומת לב remarkable  ירוש׳ מעש״ש פ״ב נ״ג ע״ג: והן נוטי נוטימי.</p>","notation":["ת׳"]},"42058":{"h":"נוטירין","r":"KRU12474","alt":["נוֹטָרִין"],"source":"krupnik","glosses":[{"text":"indictments","label":"1"},{"text":"clerks","label":"2"}],"html":"<p>1 האשמה indictments  שמו״ר פל״א: כיון שקרא נוטרין שלו וכו׳.\n2 לבלרים clerks  ירוש׳ סוטה פ״ח כ״א ע״ד: משלחין נוטריהן; תוס׳ צוק׳ שם ח׳ ו׳: ושלחו נוטירין.</p>","notation":[]},"42059":{"h":"נוֹטָרִיקוֹן","r":"KRU12475","alt":[],"source":"krupnik","glosses":[{"text":"abbreviation","label":""}],"html":"<p>קיצור, ראשי תיבות abbreviation  שמו״ר פ״ה: עשר מכות נוטריקון דצ״ך עד״ש באח״ב.</p>","notation":["ז׳"]},"42060":{"h":"נוֹי","r":"KRU12476","alt":[],"source":"krupnik","glosses":[{"text":"beauty, ornament","label":""}],"html":"<p>יופי וקישוט beauty, ornament  כל׳ פי״ד מ״ב: עשאן לנוי.</p>","notation":["ז׳"]},"42061":{"h":"נוּךְ","r":"KRU12481","alt":[],"source":"krupnik","glosses":[{"text":"cartilage of the ear","label":""}],"html":"<p>סחוס של האוזן cartilage of the ear  ספרא מצורע נגעים פרשה ג׳ פרק ג׳: תנוך וכו׳ תוך נוך וכו׳ זה גדר האמצעי.</p>","notation":["ז׳"]},"42062":{"h":"נוּכְרָא","r":"KRU12482","alt":["נוּכְרָאָה","נוּכְרַי"],"source":"krupnik","glosses":[{"text":"stranger, gentile","label":""}],"html":"<p>נכר, זר stranger, gentile  תרג׳ ש״ב ט״ו י״ט (נכרי אתה): נוכרא את; שבת ס״ה ע״ב: גופא נוכראה; תרג׳ יב״ע בר׳ ל״א ט״ו (נכריות): נוכרייתא.</p>","notation":[]},"42063":{"h":"נוּכְתְּחָא","r":"KRU12483","alt":[],"source":"krupnik","glosses":[{"text":"usury","label":""}],"html":"<p>נשך, רבית usury  תרג׳ מש׳ כ״ח ח׳ (מרבה הונו בנשך): דמסגיא מזליה בנוכתחא.</p>","notation":["נ׳"]},"42064":{"h":"נָוַל","r":"KRU12484","alt":[],"source":"krupnik","glosses":[{"text":"to degenerate","label":""}],"html":"<p>נעשה מנוול, התנוון to degenerate  תוס׳ סוטה י״ד ז׳: וסרחה כל המלכות כולה ואזלה ונולה.</p>","notation":["פ״ע"]},"42065":{"h":"נֵוִּל","r":"KRU12485","alt":[],"source":"krupnik","glosses":[{"text":"to disfigure, to disgrace","label":"פיעל,"}],"html":"<p>פיעל, גינה והכעיר to disfigure, to disgrace  נד׳ ס״ו ע״א: בנות ישראל נאות הן אלא שהעניות מנוולתן.</p>","notation":[]},"42066":{"h":"נְוַל","r":"KRU12486","alt":[],"source":"krupnik","glosses":[{"text":"to weave","label":""}],"html":"<p>ארג to weave  גיט׳ ל״ד ע״א: יתבא ונוולה.</p>","notation":["פ״י"]},"42067":{"h":"פַעל","r":"KRU12487","alt":[],"source":"krupnik","glosses":[{"text":"to be disfigured","label":""}],"html":"<p>עי׳ נַוֵּל נִוֵּל. סוטה ח׳ ע״ב: נוולי מנוויל לה. אִינַּוֵּל אתפ׳ נתכער ונתנוול to be disfigured  חול׳ י״א ע״ב: הא קא מנוול וכו׳. </p>","notation":[]},"42068":{"h":"נְוַל²","r":"KRU12488","alt":[],"source":"krupnik","glosses":[{"text":"web","label":""}],"html":"<p>ארג web  תרג׳ יש׳ ל״ח י״ב: כנול גרדאין.</p>","notation":["ז׳"]},"42069":{"h":"נוּם","r":"KRU12489","alt":[],"source":"krupnik","glosses":[{"text":"to say, to speak","label":""}],"html":"<p>אמר, דיבר to say, to speak  גיט׳ פ״ו מ״ז: נומינו לשליח.</p>","notation":["Marked biblical in source"]},"42070":{"h":"נוּם²","r":"KRU12490","alt":[],"source":"krupnik","glosses":[{"text":"to sleep, to slumber","label":""}],"html":"<p>היה ישן ונרדם to sleep, to slumber  עיר׳ ס״ה ע״א: לא בעי מר מינם פורתא.</p>","notation":["פ״ע"]},"42071":{"h":"נוֹמִי","r":"KRU12492","alt":[],"source":"krupnik","glosses":[{"text":"ulcer","label":""}],"html":"<p>מכה טריה ulcer  ב״ר פמ״ו: כנומי היא תלויה בגוף.</p>","notation":["נ׳"]},"42072":{"h":"נוּמִירוֹן","r":"KRU12493","alt":[],"source":"krupnik","glosses":[{"text":"a division of troops","label":""}],"html":"<p>גדוד צבא a division of troops  מכי׳ בשלח א׳: ואין נומירין אחת בטילה.</p>","notation":["נ׳"]},"42073":{"h":"נוּמִיתָא","r":"KRU12494","alt":[],"source":"krupnik","glosses":[{"text":"slumber","label":""}],"html":"<p>תנומה slumber  תרג׳ מש׳ ו׳ י׳ (מעט תנומה): קליל נומיתא.</p>","notation":["נ׳"]},"42074":{"h":"נון","r":"KRU12495","alt":[],"source":"krupnik","glosses":[{"text":"to fall away","label":"הִתְנַוֵּן התפ׳,"}],"html":"<p>הִתְנַוֵּן התפ׳, הלך הלוך ודל, הלך למות to fall away  חול׳ נ״ז ע״ב: משבחת והולכת כשירה וכו׳ מתנונה והולכת טריפה.</p>","notation":["Source marks no qal form"]},"42075":{"h":"נוּן","r":"KRU12496","alt":[],"source":"krupnik","glosses":[{"text":"the 14-th letter of the Alphabet","label":""}],"html":"<p>האות הי״ד בא״ב the 14-th letter of the Alphabet  נד׳ נ״ד ע״ב: נו״ן סמ״ך וכו׳.</p>","notation":["ז׳"]},"42076":{"h":"נוּן²","r":"KRU12497","alt":["נוּנָא"],"source":"krupnik","glosses":[{"text":"fish","label":""}],"html":"<p>דג fish  ב״ר פי״ג: וצד חד נון; ע״ז ל״ט ע״א: אייתא לקמיה נונא.</p>","notation":[]},"42077":{"h":"נוּף","r":"KRU12499","alt":[],"source":"krupnik","glosses":[{"text":"to swing oneself, to rise","label":"הִתְנוֹפֵף התפ׳,"}],"html":"<p>הִתְנוֹפֵף התפ׳, התרומם to swing oneself, to rise  ע״ז כ״ד ע״ב: התנופפי ברוב הדרך.</p>","notation":["Marked biblical in source"]},"42078":{"h":"נוּף²","r":"KRU12500","alt":[],"source":"krupnik","glosses":[{"text":"to wave","label":""},{"text":"to swing","label":""}],"html":"<p>התנופף ברוח to wave  יב׳ ס״ג ע״א: על לביני שיבלי חזנהו דקא נייפן. אָנֵיף  אפ׳, הניף to swing  תרג׳ יש׳ י״ג ב׳ (הניפו יד): אניפו יד. אִתְנוֹף אתפ׳, עי׳ הִתְנוֹפֵף. יב׳ ס״ג ע״א: נייפת אתנופי. </p>","notation":["פ״ע"]},"42079":{"h":"נוֹף","r":"KRU12501","alt":[],"source":"krupnik","glosses":[{"text":"boughs of a tree","label":""}],"html":"<p>כלל הענפים שבאילן boughs of a tree  מכ׳ פ״ב מ״ז: אילן וכו׳ ונופו נוטה.</p>","notation":["Marked biblical in source"]},"42080":{"h":"נוֹפֶךְ","r":"KRU12504","alt":[],"source":"krupnik","glosses":[{"text":"addition","label":""}],"html":"<p>תוספת addition  קיד׳ מ״ח ע״ב: אם הוסיף לה נופך משלו.</p>","notation":["Marked biblical in source"]},"42081":{"h":"נוּפָר","r":"KRU12505","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  יומא י׳ ע״א: כלנה זה נופר. </p>","notation":["שם מקום"]},"42082":{"h":"נוֹצָה","r":"KRU12506","alt":[],"source":"krupnik","glosses":[{"text":"goatshair","label":""}],"html":"<p>·– נוֹצָה שֶׁל עִזִּים שער עזים goatshair  שבת כ״ח ע״ב: נוצה של עזים.</p>","notation":[]},"42083":{"h":"נוֹצִיצְיָא","r":"KRU12507","alt":[],"source":"krupnik","glosses":[{"text":"pinion","label":""}],"html":"<p>נוצת הכנף pinion  תרג׳ איוב כ״ט י״ג (אם אברה חסידה ונוצה): אברה דחוריתא ונוציציהא.</p>","notation":["נ׳"]},"42084":{"h":"נוֹצְרִי","r":"KRU12508","alt":[],"source":"krupnik","glosses":[{"text":"of Nazareth (in Galilaea)","label":"1"},{"text":"Christian","label":"2"}],"html":"<p>1 איש נצרת שבגליל of Nazareth (in Galilaea)  סנה׳ מ״ג ע״ב (עפ״י קונטרס השמטות הש״ס): ישו הנוצרי.\n2 מאמין בישו הנוצרי Christian  תענ׳ כ״ז ע״ב (עפ״י הקונטרס הנ״ל): מפני הנוצרים.</p>","notation":["ת׳"]},"42085":{"h":"נוּקְבָּא","r":"KRU12509","alt":[],"source":"krupnik","glosses":[{"text":"hole","label":"1"}],"html":"<p>1  hole  שבת צ׳ ע״א: נוקבא דמרגניתא.\n2 נוּקְבָּה. ירוש׳ נדה פ״ג נ׳ ע״ד: דכר הוא נוקבא היא. </p>","notation":[]},"42086":{"h":"נוּקְבָּה","r":"KRU12510","alt":["נוּקְבְּתָא"],"source":"krupnik","glosses":[{"text":"female","label":""}],"html":"<p>נקבה, אשה, נערה female  ירוש׳ תענ׳ פ״ד ס״ט ע״א: לא הות ילדה נוקבה; תרג׳ ויק׳ כ״ז ז׳ (נקבה): נוקבתא.</p>","notation":[]},"42087":{"h":"נוּקְבְּתָא דְעֲוָון","r":"KRU12511","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>בא״י name of a place in Palestine  ירוש׳ שבי׳ פ״ו ל״ו ע״ג: נוקבתא דעוון.</p>","notation":["שם מקום"]},"42088":{"h":"נוֹקְדָּן","r":"KRU12513","alt":["נוֹקְדָּנָא"],"source":"krupnik","glosses":[{"text":"caviller","label":""}],"html":"<p>קפדן, דייקן caviller  תוס׳ בר׳ ה׳ י״ח: והנוקדנין תופסין אותו על כך; ירוש׳ בר׳ פ״ז י״א ע״ג: דצווח וכו׳ נוקדנא.</p>","notation":[]},"42089":{"h":"נוּקָנִיקָה","r":"KRU12514","alt":[],"source":"krupnik","glosses":[{"text":"sausage","label":""}],"html":"<p>נקניק, מעי ממולא בשר sausage  ירוש׳ שק׳ פ״ז נ׳ ע״ג: נוקניקה אשתכח בכנישתא דבולי.</p>","notation":["ז׳"]},"42090":{"h":"נוֹקְשֶׁה","r":"KRU12516","alt":[],"source":"krupnik","glosses":[{"text":"old, unfit for food","label":""}],"html":"<p>ישן נושן, פסול לאכילה old, unfit for food  מנח׳ נ״ד ע״א: נהו דחמץ גמור לא הוי נוקשה מיהא הוי.</p>","notation":["ז׳"]},"42091":{"h":"נוּרִי","r":"KRU12517","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  עיר׳ מ״ה ע״ב: ר׳ יוחנן בן נורי. </p>","notation":["שם איש"]},"42092":{"h":"נוּרִיתָא","r":"KRU12518","alt":[],"source":"krupnik","glosses":[{"text":"Crow-foot","label":""}],"html":"<p>מין צמח Crow-foot  חול׳ נ״ט ע״א: עיקרא דנוריתא (לגי׳ הערוך).</p>","notation":["נ׳"]},"42093":{"h":"נוּשְׁקְתָא","r":"KRU12520","alt":[],"source":"krupnik","glosses":[{"text":"kiss","label":""}],"html":"<p>נשיקה kiss  תרג׳ מש׳ כ״ז ו׳ (נשיקות שונא): נושקתא דסנאה.</p>","notation":["נ׳"]},"42094":{"h":"נְזַהּ","r":"KRU12523","alt":[],"source":"krupnik","glosses":[{"text":"to chide","label":""}],"html":"<p>גער בנזיפה to chide  שבת מ״א ע״ד: נזהיה רבה.</p>","notation":["פ״י"]},"42095":{"h":"נִזְיָא","r":"KRU12525","alt":[],"source":"krupnik","glosses":[{"text":"kernel","label":""}],"html":"<p>גרעין kernel  מו״ק י״ב ע״ב: שומשמא חזי לנזיי.</p>","notation":["ז׳"]},"42096":{"h":"נְזִיהוּתָא","r":"KRU12526","alt":[],"source":"krupnik","glosses":[{"text":"chiding","label":""}],"html":"<p>גערה chiding  סנה׳ מ״א ע״ב: מטיבותא דמר וכו׳ מנזיהותיה.</p>","notation":["נ׳"]},"42097":{"h":"נָזִיחַ","r":"KRU12527","alt":[],"source":"krupnik","glosses":[{"text":"a substitute for Nasir","label":""}],"html":"<p>אחד מכנויי נזיר a substitute for Nasir  נד׳ פ״א מ״ב: נזיק נזיח וכו׳.</p>","notation":[]},"42098":{"h":"נְזִיפָה","r":"KRU12529","alt":["נְזִיפוּתָא"],"source":"krupnik","glosses":[{"text":"a lower degree of excommunication","label":""}],"html":"<p>גערה שיש בה מעין חרם a lower degree of excommunication  מו״ק ט״ז ע״א: אין נזיפה פחות משבעה ימים; שם: נהג נזיפותא בנפשיה.</p>","notation":[]},"42099":{"h":"נְזִיקִין","r":"KRU12531","alt":[],"source":"krupnik","glosses":[{"text":"damages, injuries","label":"1"},{"text":"one of the six orders of the Mishnah","label":"2"},{"text":"collective name of the treatises Baba Kamma, Baba Metzia and Baba Bathra","label":"3"}],"html":"<p>1 חבלות והפסדים damages, injuries  ב״ק פ״א: ארבעה אבות נזיקין.\n2 אחד מששה סדרי משנה one of the six orders of the Mishnah  שבת ל״א ע״א: ישועות זה סדר נזיקין.\n3 שם כולל למסכתות בבא קמא, בבא מציעא ובבא בתרא collective name of the treatises Baba Kamma, Baba Metzia and Baba Bathra  ב״ק ק״ב ע״א: כולה נזיקין חדא מסכתא היא.</p>","notation":["ז״ר"]},"42100":{"h":"נָזִיר","r":"KRU12532","alt":[],"source":"krupnik","glosses":[{"text":"a nazarite for life","label":""}],"html":"<p>·– נְזִיר עוֹלָם נזיר לכל ימי חייו a nazarite for life  נזיר פ״א מ״ב: נזיר עולם הכביד שערו וכו׳.</p>","notation":[]},"42101":{"h":"נְזִירָא","r":"KRU12533","alt":[],"source":"krupnik","glosses":[{"text":"Nazarite","label":"1"},{"text":"name of an Amora","label":"2"}],"html":"<p>1 נזיר Nazarite  פס׳ מ׳ ע״ב: לך לך אמרינן לנזירא סחור סחור לכרמא לא תקרב.\n2 שם אמורא name of an Amora  ב״ר פי״ב: ר׳ לוי בשם ר׳ נזירא.</p>","notation":["ז׳"]},"42102":{"h":"נְזִירָה","r":"KRU12534","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":"1"},{"text":"nazarite (woman)","label":"2"}],"html":"<p>1  a man’s name  פסיק׳ דברי ירמ׳ קי״א ע״א: שמעון בן נזירה.\n2  nazarite (woman)  נז׳ י״ט ע״ב: ואמרה אם יבוא בני מן המלחמה בשלום אהא נזירה שבע שנים.\n3 עי׳ נְזִירוּת. ספרא אמור פרק ג׳ פרשה ד׳: אין נזירה אלא הפרשה. </p>","notation":[]},"42103":{"h":"נְזִירוּת","r":"KRU12535","alt":[],"source":"krupnik","glosses":[{"text":"nazariteship, abstinence","label":""}],"html":"<p>נדר נזיר, פרישות nazariteship, abstinence  נזיר פ״א מ״א: כל כינויי נזירות כנזירות.</p>","notation":["נ׳"]},"42104":{"h":"נִזֵּל","r":"KRU12536","alt":[],"source":"krupnik","glosses":[{"text":"to cause to flow","label":"פיעל,"}],"html":"<p>פיעל, טפטף, הזיב to cause to flow  ספרי דב׳ ש״ו: לסוף שאתה מנזל ומשקה.</p>","notation":[]},"42105":{"h":"נָזַף","r":"KRU12538","alt":[],"source":"krupnik","glosses":[{"text":"to chide","label":""}],"html":"<p>גער to chide  במ״ר פי״ג: נזף בו משה.</p>","notation":["פ״י"]},"42106":{"h":"נזק","r":"KRU12540","alt":[],"source":"krupnik","glosses":[{"text":"to damage, to injure","label":"הִזִּיק הפ׳,"}],"html":"<p>הִזִּיק הפ׳, גרם נזק וחבלה to damage, to injure  ב״ק פ״א מ״א: שדרכן להזיק ושמירתן עליך.</p>","notation":["Source marks no qal form"]},"42107":{"h":"נִזּוֹק","r":"KRU12541","alt":["נִזַּק"],"source":"krupnik","glosses":[{"text":"to be hurt","label":"נפ׳,"}],"html":"<p>נפ׳, נחבל, נגרם לו הפסד to be hurt  ב״ק פ״א מ״ד: שור המזיק ברשות הניזק; פס׳ ח׳ ע״ב: שלוחי מצוה אינן ניזוקין.</p>","notation":[]},"42108":{"h":"נַזֵּק","r":"KRU12542","alt":[],"source":"krupnik","glosses":[{"text":"to injure","label":"פַעל, אַזֵּק אפ׳,"},{"text":"to be hurt","label":"אִתְנְזַק, אִיתַּזַק אתפ׳,"}],"html":"<p>פַעל, אַזֵּק אפ׳, הזיק to injure  תרג׳ דהי״א ט״ז כ״ב (אל תגעו במשיחי): לא תנזקון בקדישי; גיט׳ נ״ג ע״א: לאזוקי קא מכוין.\nאִתְנְזַק, אִיתַּזַק אתפ׳, ניזק to be hurt  ויק״ר פכ״ד: ולית אתון מתנזקין; קיד׳ כ״ט ע״ב: הוו מיתזקי.</p>","notation":[]},"42109":{"h":"נְזַר","r":"KRU12543","alt":[],"source":"krupnik","glosses":[{"text":"to vow to be a Nazarite","label":""}],"html":"<p>נדר נֵדר נזירות to vow to be a Nazarite  נדר׳ ט׳ ע״ב: כמוך ירבו נוזרי נזירות בישראל.</p>","notation":["פ״ע"]},"42110":{"h":"נֹחַ בֶּן נֹחַ","r":"KRU12544","alt":[],"source":"krupnik","glosses":[{"text":"Gentile","label":""}],"html":"<p>אינו יהודי Gentile  סנה׳ נ״ו ע״ב: דברים שב״ד של ישראל ממיתין עליהן בן נח מוזהר עליהן.</p>","notation":["Marked biblical in source"]},"42111":{"h":"נֶחְבָּל","r":"KRU12545","alt":[],"source":"krupnik","glosses":[{"text":"the complainant in a case of battery","label":""}],"html":"<p>התובע בענין חבלה ונזקי גוף the complainant in a case of battery  שבוע׳ פ״ז מ״א: ואלו נשבעין ונוטלין השכיר והנגזל והנחבל.</p>","notation":["ז׳"]}};
